globalThis.LEXAR_WORK_DATA = {"acarnesi":{"speeches":[{"id":"ach-sp-0001","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὅσα δὴ δέδηγμαι τὴν ἐμαυτοῦ καρδίαν,","ἥσθην δὲ βαιά, πάνυ δὲ βαιά, τέτταρα·","ἃ δ' ὠδυνήθην, ψαμμακοσιογάργαρα.","Φέρ' ἴδω, τί δ' ἥσθην ἄξιον χαιρηδόνος;","Ἐγᾦδ' ἐφ' ᾧ γε τὸ κέαρ εὐφράνθην ἰδών,","τοῖς πέντε ταλάντοις οἷς Κλέων ἐξήμεσεν.","Ταῦθ' ὡς ἐγανώθην, καὶ φιλῶ τοὺς ἱππέας","διὰ τοῦτο τοὔργον· ἄξιον γὰρ Ἑλλάδι.","Ἀλλ' ὠδυνήθην ἕτερον αὖ τραγῳδικόν,","ὅτε δὴ 'κεχήνη προσδοκῶν τὸν Αἰσχύλον,","ὁ δ' ἀνεῖπεν· \"Εἴσαγ', ὦ Θέογνι, τὸν χορόν\".","Πῶς τοῦτ' ἔσεισέ μου δοκεῖς τὴν καρδίαν;","Ἀλλ' ἕτερον ἥσθην, ἡνίκ' ἐπὶ Μόσχῳ ποτὲ","Δεξίθεος εἰσῆλθ' ᾀσόμενος Βοιώτιον.","Τῆτες δ' ἀπέθανον καὶ διεστράφην ἰδών,","ὅτε δὴ παρέκυψε Χαῖρις ἐπὶ τὸν ὄρθιον.","Ἀλλ' οὐδεπώποτ' ἐξ ὅτου 'γὼ ῥύπτομαι","οὕτως ἐδήχθην ὑπὸ κονίας τὰς ὀφρῦς","ὡς νῦν, ὁπότ' οὔσης κυρίας ἐκκλησίας","ἑωθινῆς ἔρημος ἡ πνὺξ αὑτηί,","οἱ δ' ἐν ἀγορᾷ λαλοῦσι κἄνω καὶ κάτω","τὸ σχοινίον φεύγουσι τὸ μεμιλτωμένον.","Οὐδ' οἱ πρυτάνεις ἥκουσιν, ἀλλ' ἀωρίαν","ἥκοντες, εἶτα δ' ὠστιοῦνται πῶς δοκεῖς","ἐλθόντες ἀλλήλοισι περὶ πρώτου ξύλου,","ἁθρόοι καταρρέοντες· εἰρήνη δ' ὅπως","ἔσται προτιμῶσ' οὐδέν· ὦ πόλις πόλις.","Ἐγὼ δ' ἀεὶ πρώτιστος εἰς ἐκκλησίαν","νοστῶν κάθημαι· κᾆτ' ἐπειδὰν ὦ μόνος,","στένω, κέχηνα, σκορδινῶμαι, πέρδομαι,","ἀπορῶ, γράφω, παρατίλλομαι, λογίζομαι,","ἀποβλέπων εἰς τὸν ἀγρόν, εἰρήνης ἐρῶν,","στυγῶν μὲν ἄστυ, τὸν δ' ἐμὸν δῆμον ποθῶν,","ὃς οὐδεπώποτ' εἶπεν· \"Ἄνθρακας πρίω\",","οὐκ ὄξος, οὐκ ἔλαιον, οὐδ' ᾔδει πρίω,","ἀλλ' αὐτὸς ἔφερε πάντα χὠ πρίων ἀπῆν.","Νῦν οὖν ἀτεχνῶς ἥκω παρεσκευασμένος","βοᾶν, ὑποκρούειν, λοιδορεῖν τοὺς ῥήτορας,","ἐάν τις ἄλλο πλὴν περὶ εἰρήνης λέγῃ.","Ἀλλ' οἱ πρυτάνεις γὰρ οὑτοιὶ μεσημβρινοί.","Οὐκ ἠγόρευον; τοῦτ' ἐκεῖν' οὑγὼ 'λεγον·","εἰς τὴν προεδρίαν πᾶς ἀνὴρ ὠστίζεται."]},{"id":"ach-sp-0002","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Πάριτ' εἰς τὸ πρόσθεν,","πάριθ', ὡς ἂν ἐντὸς ἦτε τοῦ καθάρματος."]},{"id":"ach-sp-0003","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ἤδη τις εἶπε;"]},{"id":"ach-sp-0004","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Τίς ἀγορεύειν βούλεται;"]},{"id":"ach-sp-0005","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ἐγώ."]},{"id":"ach-sp-0006","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Τίς ὤν;"]},{"id":"ach-sp-0007","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ἀμφίθεος."]},{"id":"ach-sp-0008","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Οὐκ ἄνθρωπος;"]},{"id":"ach-sp-0009","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Οὔ,","ἀλλ' ἀθάνατος. Ὁ γὰρ Ἀμφίθεος Δήμητρος ἦν","καὶ Τριπτολέμου· τούτου δὲ Κελεὸς γίγνεται·","γαμεῖ δὲ Κελεὸς Φαιναρέτην τήθην ἐμήν,","ἐξ ἧς Λυκῖνος ἐγένετ'· ἐκ τούτου δ' ἐγώ.","Ἀθάνατός εἰμ'· ἐμοὶ δ' ἐπέτρεψαν οἱ θεοὶ","σπονδὰς ποεῖσθαι πρὸς Λακεδαιμονίους μόνῳ.","Ἀλλ' ἀθάνατος ὤν, ἄνδρες, ἐφόδι' οὐκ ἔχω·","οὐ γὰρ διδόασιν οἱ πρυτάνεις."]},{"id":"ach-sp-0010","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Οἱ τοξόται."]},{"id":"ach-sp-0011","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ὦ Τριπτόλεμε καὶ Κελεέ, περιόψεσθέ με;"]},{"id":"ach-sp-0012","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦνδρες πρυτάνεις, ἀδικεῖτε τὴν ἐκκλησίαν","τὸν ἄνδρ' ἀπάγοντες, ὅστις ἡμῖν ἤθελεν","σπονδὰς ποεῖσθαι καὶ κρεμάσαι τὰς ἀσπίδας."]},{"id":"ach-sp-0013","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Κάθησο, σῖγα."]},{"id":"ach-sp-0014","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μὰ τὸν Ἀπόλλω 'γὼ μὲν οὔ,","ἢν μὴ περὶ εἰρήνης γε πρυτανεύσητέ μοι."]},{"id":"ach-sp-0015","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Οἱ πρέσβεις οἱ παρὰ βασιλέως."]},{"id":"ach-sp-0016","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ποίου βασιλέως; Ἄχθομαι 'γὼ πρέσβεσιν","καὶ τοῖς ταὧσι τοῖς τ' ἀλαζονεύμασιν."]},{"id":"ach-sp-0017","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Σίγα."]},{"id":"ach-sp-0018","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Βαβαιάξ. Ὦκβάτανα τοῦ σχήματος."]},{"id":"ach-sp-0019","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Ἐπέμψαθ' ἡμᾶς ὡς βασιλέα τὸν μέγαν","μισθὸν φέροντας δύο δραχμὰς τῆς ἡμέρας","ἐπ' Εὐθυμένους ἄρχοντος."]},{"id":"ach-sp-0020","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οἴμοι τῶν δραχμῶν."]},{"id":"ach-sp-0021","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Καὶ δῆτ' ἐτρυχόμεσθα τῶν Καϋστρίων","πεδίων ὁδοιπλανοῦντες ἐσκηνημένοι,","ἐφ' ἁρμαμαξῶν μαλθακῶς κατακείμενοι,","ἀπολλύμενοι."]},{"id":"ach-sp-0022","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Σφόδρα γὰρ ἐσῳζόμην ἐγὼ","παρὰ τὴν ἔπαλξιν ἐν φορυτῷ κατακείμενος."]},{"id":"ach-sp-0023","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Ξενιζόμενοι δὲ πρὸς βίαν ἐπίνομεν","ἐξ ὑαλίνων ἐκπωμάτων καὶ χρυσίδων","ἄκρατον οἶνον ἡδύν."]},{"id":"ach-sp-0024","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ Κραναὰ πόλις,","ἆρ' αἰσθάνει τὸν κατάγελων τῶν πρέσβεων;"]},{"id":"ach-sp-0025","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Οἱ βάρβαροι γὰρ ἄνδρας ἡγοῦνται μόνους","τοὺς πλεῖστα δυναμένους φαγεῖν τε καὶ πιεῖν."]},{"id":"ach-sp-0026","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἡμεῖς δὲ λαικαστάς τε καὶ καταπύγονας."]},{"id":"ach-sp-0027","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Ἔτει τετάρτῳ δ' εἰς τὰ βασίλει' ἤλθομεν·","ἀλλ' εἰς ἀπόπατον ᾤχετο στρατιὰν λαβών,","κἄχεζεν ὀκτὼ μῆνας ἐπὶ χρυσῶν ὀρῶν."]},{"id":"ach-sp-0028","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Πόσου δὲ τὸν πρωκτὸν χρόνου ξυνήγαγεν;","Τῇ πανσελήνῳ;"]},{"id":"ach-sp-0029","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Κᾆτ' ἀπῆλθεν οἴκαδε.","Εἶτ' ἐξένιζε παρετίθει θ' ἡμῖν ὅλους","ἐκ κριβάνου βοῦς."]},{"id":"ach-sp-0030","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καὶ τίς εἶδε πώποτε","βοῦς κριβανίτας; Τῶν ἀλαζονευμάτων."]},{"id":"ach-sp-0031","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Καὶ ναὶ μὰ Δί' ὄρνιν τριπλάσιον Κλεωνύμου","παρέθηκεν ἡμῖν· ὄνομα δ' ἦν αὐτῷ φέναξ."]},{"id":"ach-sp-0032","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ταῦτ' ἄρ' ἐφενάκιζες σὺ δύο δραχμὰς φέρων."]},{"id":"ach-sp-0033","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Καὶ νῦν ἄγοντες ἥκομεν Ψευδαρτάβαν,","τὸν βασιλέως Ὀφθαλμόν."]},{"id":"ach-sp-0034","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐκκόψειέ γε","κόραξ πατάξας, τόν γε σὸν τοῦ πρέσβεως."]},{"id":"ach-sp-0035","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Ὁ βασιλέως Ὀφθαλμός."]},{"id":"ach-sp-0036","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦναξ Ἡράκλεις.","Πρὸς τῶν θεῶν, ἄνθρωπε, ναύφρακτον βλέπεις,","ἢ περὶ ἄκραν κάμπτων νεώσοικον σκοπεῖς;","Ἄσκωμ' ἔχεις που περὶ τὸν ὀφθαλμὸν κάτω;"]},{"id":"ach-sp-0037","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Ἄγε δὴ σὺ βασιλεὺς ἅττα σ' ἀπέπεμψεν φράσον","λέξοντ' Ἀθηναίοισιν, ὦ Ψευδαρτάβα."]},{"id":"ach-sp-0038","scene":"1","section_id":"ach-div-001","speaker":"Pseudoartabano","speaker_ref":"#pseudoartabano","lines":["Ι αρταμανε Ξαρξας απιαονα σατρα."]},{"id":"ach-sp-0039","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Ξυνῆκας ὃ λέγει;"]},{"id":"ach-sp-0040","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μὰ τὸν Ἀπόλλω 'γὼ μὲν οὔ."]},{"id":"ach-sp-0041","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Πέμψειν βασιλέα φησὶν ὑμῖν χρυσίον.","Λέγε δὴ σὺ μεῖζον καὶ σαφῶς τὸ χρυσίον."]},{"id":"ach-sp-0042","scene":"1","section_id":"ach-div-001","speaker":"Pseudoartabano","speaker_ref":"#pseudoartabano","lines":["Οὐ ληψι χρυσο, χαυνόπρωκτ' Ἰαοναυ."]},{"id":"ach-sp-0043","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οἴμοι κακοδαίμων ὡς σαφῶς."]},{"id":"ach-sp-0044","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Τί δαὶ λέγει;"]},{"id":"ach-sp-0045","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὅ τι; χαυνοπρώκτους τοὺς Ἰάονας λέγει,","εἰ προσδοκῶσι χρυσίον ἐκ τῶν βαρβάρων."]},{"id":"ach-sp-0046","scene":"1","section_id":"ach-div-001","speaker":"Vecchio","speaker_ref":"#vecchio","lines":["Οὔκ, ἀλλ' ἀχάνας ὅδε γε χρυσίου λέγει."]},{"id":"ach-sp-0047","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ποίας ἀχάνας; Σὺ μὲν ἀλαζὼν εἶ μέγας.","Ἀλλ' ἄπιθ'· ἐγὼ δὲ βασανιῶ τοῦτον μόνος.","Ἄγε δὴ σὺ φράσον ἐμοὶ σαφῶς πρὸς τουτονί,","ἵνα μή σε βάψω βάμμα Σαρδιανικόν·","βασιλεὺς ὁ μέγας ἡμῖν ἀποπέμψει χρυσίον; ‑","Ἄλλως ἄρ' ἐξαπατώμεθ' ὑπὸ τῶν πρέσβεων; ‑","Ἑλληνικόν γ' ἐπένευσαν ἄνδρες οὑτοιί,","κοὐκ ἔσθ' ὅπως οὐκ εἰσὶν ἐνθένδ' αὐτόθεν.","Καὶ τοῖν μὲν εὐνούχοιν τὸν ἕτερον τουτονὶ","ἐγᾦδ' ὅς ἐστι, Κλεισθένης ὁ Σιβυρτίου.","Ὦ θερμόβουλον πρωκτὸν ἐξυρημένε.","Τοιόνδε δ', ὦ πίθηκε, τὸν πώγων' ἔχων","εὐνοῦχος ἡμῖν ἦλθες ἐσκευασμένος;","Ὁδὶ δὲ τίς ποτ' ἐστίν; οὐ δήπου Στράτων;"]},{"id":"ach-sp-0048","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Σίγα, κάθιζε.","Τὸν βασιλέως Ὀφθαλμὸν ἡ βουλὴ καλεῖ","εἰς τὸ πρυτανεῖον."]},{"id":"ach-sp-0049","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ταῦτα δῆτ' οὐκ ἀγχόνη;","Κἄπειτ' ἐγὼ δῆτ' ἐνθαδὶ στραγγεύομαι,","τοὺς δὲ ξενίζειν οὐδέποτ' ἴσχει γ' ἡ θύρα;","Ἀλλ' ἐργάσομαί τι δεινὸν ἔργον καὶ μέγα.","Ἀλλ' Ἀμφίθεός μοι ποῦ 'στιν;"]},{"id":"ach-sp-0050","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Οὑτοσὶ πάρα."]},{"id":"ach-sp-0051","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐμοὶ σὺ ταυτασὶ λαβὼν ὀκτὼ δραχμὰς","σπονδὰς πόησαι πρὸς Λακεδαιμονίους μόνῳ","καὶ τοῖσι παιδίοισι καὶ τῇ πλάτιδι·","ὑμεῖς δὲ πρεσβεύεσθε καὶ κεχήνετε"]},{"id":"ach-sp-0052","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Προσίτω Θέωρος ὁ παρὰ Σιτάλκους."]},{"id":"ach-sp-0053","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["Ὁδί."]},{"id":"ach-sp-0054","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἕτερος ἀλαζὼν οὗτος εἰσκηρύττεται."]},{"id":"ach-sp-0055","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["Χρόνον μὲν οὐκ ἂν ἦμεν ἐν Θρᾴκῃ πολύν, ‑"]},{"id":"ach-sp-0056","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μὰ Δί' οὐκ ἄν, εἰ μισθόν γε μὴ 'φερες πολύν."]},{"id":"ach-sp-0057","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["εἰ μὴ κατένειψε χιόνι τὴν Θρᾴκην ὅλην","καὶ τοὺς ποταμοὺς ἔπηξ', ‑"]},{"id":"ach-sp-0058","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["ὑπ' αὐτὸν τὸν χρόνον.","ὅτ' ἐνθαδὶ Θέογνις ἠγωνίζετο."]},{"id":"ach-sp-0059","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["Τοῦτον μετὰ Σιτάλκους ἔπινον τὸν χρόνον.","Καὶ δῆτα φιλαθήναιος ἦν ὑπερφυῶς","ὑμῶν τ' ἐραστὴς ὡς ἀληθῶς, ὥστε καὶ","ἐν τοῖσι τοίχοις ἔγραφ'· \"Ἀθηναῖοι καλοί\".","δ' υἱός, ὃν Ἀθηναῖον ἐπεποήμεθα,","ἤρα φαγεῖν ἀλλᾶντας ἐξ Ἀπατουρίων,","καὶ τὸν πατέρ' ἠντεβόλει βοηθεῖν τῇ πάτρᾳ·","ὁ δ' ὤμοσε σπένδων βοηθήσειν ἔχων","στρατιὰν τοσαύτην ὥστ' Ἀθηναίους ἐρεῖν·","\"Ὅσον τὸ χρῆμα παρνόπων προσέρχεται\"."]},{"id":"ach-sp-0060","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κάκιστ' ἀπολοίμην, εἴ τι τούτων πείθομαι","ὧν εἶπας ἐνταυθοῖ σὺ πλὴν τῶν παρνόπων."]},{"id":"ach-sp-0061","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["Καὶ νῦν ὅπερ μαχιμώτατον Θρᾳκῶν ἔθνος","ἔπεμψεν ὑμῖν."]},{"id":"ach-sp-0062","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τοῦτο μέν γ' ἤδη σαφές."]},{"id":"ach-sp-0063","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Οἱ Θρᾷκες ἴτε δεῦρ', οὓς Θέωρος ἤγαγεν."]},{"id":"ach-sp-0064","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τουτὶ τί ἐστι τὸ κακόν;"]},{"id":"ach-sp-0065","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["Ὀδομάντων στρατός."]},{"id":"ach-sp-0066","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ποίων Ὀδομάντων; εἰπέ μοι, τουτὶ τί ἦν;","Τίς τῶν Ὀδομάντων τὸ πέος ἀποτεθρίακεν;"]},{"id":"ach-sp-0067","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["Τούτοις ἐάν τις δύο δραχμὰς μισθὸν διδῷ,","καταπελτάσονται τὴν Βοιωτίαν ὅλην."]},{"id":"ach-sp-0068","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τοισδὶ δύο δραχμὰς τοῖς ἀπεψωλημένοις;","Ὑποστένοι μέντἂν ὁ θρανίτης λεώς,","ὁ σωσίπολις. Οἴμοι τάλας ἀπόλλυμαι,","ὑπὸ τῶν Ὀδομάντων τὰ σκόροδα πορθούμενος.","Οὐ καταβαλεῖτε τὰ σκόροδ';"]},{"id":"ach-sp-0069","scene":"1","section_id":"ach-div-001","speaker":"Teoro","speaker_ref":"#teoro","lines":["Ὦ μόχθηρε σύ,","οὐ μὴ πρόσει τούτοισιν ἐσκοροδισμένοις."]},{"id":"ach-sp-0070","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ταυτὶ περιείδεθ' οἱ πρυτάνεις πάσχοντά με","ἐν τῇ πατρίδι καὶ ταῦθ' ὑπ' ἀνδρῶν βαρβάρων;","Ἀλλ' ἀπαγορεύω μὴ ποεῖν ἐκκλησίαν","τοῖς Θρᾳξὶ περὶ μισθοῦ· λέγω δ' ὑμῖν ὅτι","διοσημία 'στὶ καὶ ῥανὶς βέβληκέ με."]},{"id":"ach-sp-0071","scene":"1","section_id":"ach-div-001","speaker":"Araldo","speaker_ref":"#araldo","lines":["Τοὺς Θρᾷκας ἀπιέναι, παρεῖναι δ' εἰς ἕνην·","Οἱ γὰρ πρυτάνεις λύουσι τὴν ἐκκλησίαν."]},{"id":"ach-sp-0072","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οἴμοι τάλας, μυττωτὸν ὅσον ἀπώλεσα.","Ἀλλ' ἐκ Λακεδαίμονος γὰρ Ἀμφίθεος ὁδί.","Χαῖρ' Ἀμφίθεε."]},{"id":"ach-sp-0073","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Μήπω γε πρίν ‹γ'› ἂν στῶ τρέχων·","δεῖ γάρ με φεύγοντ' ἐκφυγεῖν Ἀχαρνέας."]},{"id":"ach-sp-0074","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί δ' ἐστίν;"]},{"id":"ach-sp-0075","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ἐγὼ μὲν δεῦρό σοι σπονδὰς φέρων","ἔσπευδον· οἱ δ' ὤσφροντο πρεσβῦταί τινες","Ἀχαρνικοί, στιπτοὶ γέροντες, πρίνινοι,","ἀτεράμονες, Μαραθωνομάχαι, σφενδάμνινοι.","Ἔπειτ' ἀνέκραγον πάντες· \"Ὦ μιαρώτατε,","σπονδὰς φέρεις τῶν ἀμπέλων τετμημένων;\"","Κἀς τοὺς τρίβωνας ξυνελέγοντο τῶν λίθων·","ἐγὼ δ' ἔφευγον· οἱ δ' ἐδίωκον κἀβόων."]},{"id":"ach-sp-0076","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οἱ δ' οὖν βοώντων. Ἀλλὰ τὰς σπονδὰς φέρεις;"]},{"id":"ach-sp-0077","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ἔγωγέ, φημι, τρία γε ταυτὶ γεύματα.","Αὗται μέν εἰσι πεντέτεις. Γεῦσαι λαβών."]},{"id":"ach-sp-0078","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Αἰβοῖ."]},{"id":"ach-sp-0079","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Τί ἐστιν;"]},{"id":"ach-sp-0080","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐκ ἀρέσκουσίν μ' ὅτι","ὄζουσι πίττης καὶ παρασκευῆς νεῶν."]},{"id":"ach-sp-0081","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Σὺ δ' ἀλλὰ τασδὶ τὰς δεκέτεις γεῦσαι λαβών."]},{"id":"ach-sp-0082","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὄζουσι χαὖται πρέσβεων εἰς τὰς πόλεις","ὀξύτατον ὥσπερ διατριβῆς τῶν ξυμμάχων."]},{"id":"ach-sp-0083","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ἀλλ' αὑταιί τοί σοι τριακοντούτιδες","κατὰ γῆν τε καὶ θάλατταν."]},{"id":"ach-sp-0084","scene":"1","section_id":"ach-div-001","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ Διονύσια,","αὗται μὲν ὄζουσ' ἀμβροσίας καὶ νέκταρος","καὶ μὴ 'πιτηρεῖν σιτί' ἡμερῶν τριῶν,","κἀν τῷ στόματι λέγουσι· \"Βαῖν' ὅπῃ 'θέλεις\".","Ταύτας δέχομαι καὶ σπένδομαι κἀκπίομαι,","χαίρειν κελεύων πολλὰ τοὺς Ἀχαρνέας.","Ἐγὼ δὲ πολέμου καὶ κακῶν ἀπαλλαγεὶς","ἄξω τὰ κατ' ἀγροὺς εἰσιὼν Διονύσια."]},{"id":"ach-sp-0085","scene":"1","section_id":"ach-div-001","speaker":"Anfiteo","speaker_ref":"#anfiteo","lines":["Ἐγὼ δὲ φευξοῦμαί γε τοὺς Ἀχαρνέας."]},{"id":"ach-sp-0086","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Τῇδε πᾶς ἕπου, δίωκε καὶ τὸν ἄνδρα πυνθάνου","τῶν ὁδοιπόρων ἁπάντων· τῇ πόλει γὰρ ἄξιον","ξυλλαβεῖν τὸν ἄνδρα τοῦτον. Ἀλλά μοι μηνύσατε,","εἴ τις οἶδ' ὅποι τέτραπται γῆς ὁ τὰς σπονδὰς φέρων.","Ἐκπέφευγ', οἴχεται φροῦδος. Οἴ-","μοι τάλας τῶν ἐτῶν τῶν ἐμῶν·","οὐκ ἂν ἐπ' ἐμῆς γε νεότητος, ὅτ' ἐ-","γὼ φέρων ἀνθράκων φορτίον","ἠκολούθουν Φαΰλλῳ τρέχων, ὧδε φαύλως ἂν ὁ","σπονδοφόρος οὗτος ὑπ' ἐμοῦ τότε διωκόμενος","ἐξέφυγεν οὐδ' ἂν ἐλαφρῶς ἂν ἀπεπλίξατο."]},{"id":"ach-sp-0087","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Νῦν δ' ἐπειδὴ στερρὸν ἤδη τοὐμὸν ἀντικνήμιον","καὶ παλαιῷ Λακρατείδῃ τὸ σκέλος βαρύνεται,","οἴχεται. Διωκτέος δέ· μὴ γὰρ ἐγχάνοι ποτὲ","μηδέ περ γέροντας ὄντας ἐκφυγὼν Ἀχαρνέας,","ὅστις, ὦ Ζεῦ πάτερ καὶ θεοί,","τοῖσιν ἐχθροῖσιν ἐσπείσατο,","οἷσι παρ' ἐμοῦ πόλεμος ἐχθοδοπὸς","αὔξεται τῶν ἐμῶν χωρίων·","κοὐκ ἀνήσω πρὶν ἂν σχοῖνος αὐτοῖσιν ἀντεμπαγῶ","ὀξύς, ὀδυνηρός, ‹ἐπίω θ' ἅμ'› ἐπίκωπος, ἵνα","μήποτε πατῶσιν ἔτι τὰς ἐμὰς ἀμπέλους"]},{"id":"ach-sp-0088","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Ἀλλὰ δεῖ ζητεῖν τὸν ἄνδρα καὶ βλέπειν Βαλλήναδε","καὶ διώκειν γῆν πρὸ γῆς, ἕως ἂν εὑρεθῇ ποτέ·","ὡς ἐγὼ βάλλων ἐκεῖνον οὐκ ἂν ἐμπλῄμην λίθοις."]},{"id":"ach-sp-0089","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Εὐφημεῖτε, εὐφημεῖτε."]},{"id":"ach-sp-0090","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Σῖγα πᾶς. Ἠκούσατ', ἄνδρες, ἆρα τῆς εὐφημίας;","Οὗτος αὐτός ἐστιν ὃν ζητοῦμεν. Ἀλλὰ δεῦρο πᾶς","ἐκποδών· θύσων γὰρ ἁνήρ, ὡς ἔοικ', ἐξέρχεται."]},{"id":"ach-sp-0091","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Εὐφημεῖτε, εὐφημεῖτε.","Πρόιθ' εἰς τὸ πρόσθεν ὀλίγον, ἡ κανηφόρος.","Ὁ Ξανθίας τὸν φαλλὸν ὀρθὸν στησάτω.","Κατάθου τὸ κανοῦν, ὦ θύγατερ, ἵν' ἀπαρξώμεθα."]},{"id":"ach-sp-0092","scene":"Coro 1","section_id":"ach-div-002","speaker":"Figlia","speaker_ref":"#figlia","lines":["Ὦ μῆτερ, ἀνάδος δεῦρο τὴν ἐτνήρυσιν,","ἵν' ἔτνος καταχέω τοὐλατῆρος τουτουί."]},{"id":"ach-sp-0093","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καὶ μὴν καλόν γ' ἔστ'. Ὦ Διόνυσε δέσποτα,","κεχαρισμένως σοι τήνδε τὴν πομπὴν ἐμὲ","πέμψαντα καὶ θύσαντα μετὰ τῶν οἰκετῶν","ἀγαγεῖν τυχηρῶς τὰ κατ' ἀγροὺς Διονύσια,","στρατιᾶς ἀπαλλαχθέντα, τὰς σπονδὰς δέ μοι","καλῶς ξυνενεγκεῖν τὰς τριακοντούτιδας.","Ἄγ', ὦ θύγατερ, ὅπως τὸ κανοῦν καλὴ καλῶς","οἴσεις βλέπουσα θυμβροφάγον. Ὡς μακάριος","ὅστις σ' ὀπύσει κἀκποήσεται γαλᾶς","σοῦ μηδὲν ἥττους βδεῖν, ἐπειδὰν ὄρθρος ᾖ.","Πρόβαινε, κἀν τὤχλῳ φυλάττεσθαι σφόδρα","μή τις λαθών σου περιτράγῃ τὰ χρυσία.","Ὦ Ξανθία, σφῷν δ' ἐστὶν ὀρθὸς ἑκτέος","ὁ φαλλὸς ἐξόπισθε τῆς κανηφόρου·","ἐγὼ δ' ἀκολουθῶν ᾄσομαι τὸ φαλλικόν·","σὺ δ', ὦ γύναι, θεῶ μ' ἀπὸ τοῦ τέγους. Πρόβα."]},{"id":"ach-sp-0094","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Φαλῆς, ἑταῖρε Βακχίου,","ξύγκωμε, νυκτοπεριπλάνη-","τε, μοιχέ, παιδεραστά,","ἕκτῳ σ' ἔτει προσεῖπον εἰς","τὸν δῆμον ἐλθὼν ἄσμενος,","σπονδὰς ποησάμενος ἐμαυ-","τῷ, πραγμάτων τε καὶ μαχῶν","καὶ Λαμάχων ἀπαλλαγείς.","Πολλῷ γάρ ἐσθ' ἥδιον, ὦ Φαλῆς Φαλῆς,","κλέπτουσαν εὑρόνθ' ὡρικὴν ὑληφόρον,","τὴν Στρυμοδώρου Θρᾷτταν ἐκ τοῦ φελλέως,","μέσην λαβόντ', ἄραντα, κατα-","βαλόντα καταγιγαρτίσαι.","Φαλῆς Φαλῆς,","ἐὰν μεθ' ἡμῶν ξυμπίῃς, ἐκ κραιπάλης","ἕωθεν εἰρήνης ῥοφήσεις τρύβλιον·","ἡ δ' ἀσπὶς ἐν τῷ φεψάλῳ κρεμήσεται."]},{"id":"ach-sp-0095","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Οὗτος αὐτός ἐστιν, οὗτος·","βάλλε, βάλλε, βάλλε, βάλλε,","παῖε παῖε τὸν μιαρόν.","Οὐ βαλεῖς, οὐ βαλεῖς;"]},{"id":"ach-sp-0096","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἡράκλεις τουτὶ τί ἐστι; τὴν χύτραν συντρίψετε."]},{"id":"ach-sp-0097","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Σὲ μὲν οὖν καταλεύσομεν, ὦ μιαρὰ κεφαλή."]},{"id":"ach-sp-0098","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀντὶ ποίας αἰτίας, ὦχαρνέων γεραίτατοι;"]},{"id":"ach-sp-0099","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Τοῦτ' ἐρωτᾷς; Ἀναίσχυντος εἶ καὶ βδελυρός,","ὦ προδότα τῆς πατρίδος, ὅστις ἡμῶν μόνος","σπεισάμενος εἶτα δύνασαι πρὸς ἔμ' ἀποβλέπειν."]},{"id":"ach-sp-0100","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀντὶ δ' ὧν ἐσπεισάμην ἠκούσατ'; Ἀλλ' ἀκούσατε."]},{"id":"ach-sp-0101","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Σοῦ γ' ἀκούσωμεν; Ἀπολεῖ· κατά σε χώσομεν τοῖς λίθοις."]},{"id":"ach-sp-0102","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μηδαμῶς πρὶν ἄν γ' ἀκούσητ'· ἀλλ' ἀνάσχεσθ', ὦγαθοί."]},{"id":"ach-sp-0103","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Οὐκ ἀνασχήσομαι· μηδὲ λέγε μοι σὺ λόγον·","ὡς μεμίσηκά σε Κλέωνος ἔτι μᾶλλον, ὃν","κατατεμῶ τοῖσιν ἱππεῦσι καττύματα.","Σοῦ δ' ἐγὼ λόγους λέγοντος οὐκ ἀκούσομαι μακρούς,","ὅστις ἐσπείσω Λάκωσιν, ἀλλὰ τιμωρήσομαι."]},{"id":"ach-sp-0104","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦγαθοί, τοὺς μὲν Λάκωνας ἐκποδὼν ἐάσατε,","τῶν δ' ἐμῶν σπονδῶν ἀκούσατ', εἰ καλῶς ἐσπεισάμην."]},{"id":"ach-sp-0105","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Πῶς δ' ἔτ' ἂν καλῶς λέγοις ἄν, εἴπερ ἐσπείσω γ' ἅπαξ","οἷσιν οὔτε βωμὸς οὔτε πίστις οὔθ' ὅρκος μένει;"]},{"id":"ach-sp-0106","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οἶδ' ἐγὼ καὶ τοὺς Λάκωνας, οἷς ἄγαν ἐγκείμεθα,","οὐχ ἁπάντων ὄντας ἡμῖν αἰτίους τῶν πραγμάτων."]},{"id":"ach-sp-0107","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Οὐχ ἁπάντων, ὦ πανοῦργε; ταῦτα δὴ τολμᾷς λέγειν","ἐμφανῶς ἤδη πρὸς ἡμᾶς; Εἶτ' ἐγώ σου φείσομαι;"]},{"id":"ach-sp-0108","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐχ ἁπάντων, οὐχ ἁπάντων· ἀλλ' ἐγὼ λέγων ὁδὶ","πόλλ' ἂν ἀποφήναιμ' ἐκείνους ἔσθ' ἃ κἀδικουμένους."]},{"id":"ach-sp-0109","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Τοῦτο τοὔπος δεινὸν ἤδη καὶ ταραξικάρδιον,","εἰ σὺ τολμήσεις ὑπὲρ τῶν πολεμίων ἡμῖν λέγειν."]},{"id":"ach-sp-0110","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κἄν γε μὴ λέγω δίκαια μηδὲ τῷ πλήθει δοκῶ,","ὑπὲρ ἐπιξήνου 'θελήσω τὴν κεφαλὴν ἔχων λέγειν."]},{"id":"ach-sp-0111","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Εἰπέ μοι, τί φειδόμεσθα τῶν λίθων, ὦ δημόται,","μὴ οὐ καταξαίνειν τὸν ἄνδρα τοῦτον εἰς φοινικίδα;"]},{"id":"ach-sp-0112","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οἷον αὖ μέλας τις ὑμῖν θυμάλωψ ἐπέζεσεν.","Οὐκ ἀκούσεσθ', οὐκ ἀκούσεσθ' ἐτεόν, ὦχαρνηίδαι;"]},{"id":"ach-sp-0113","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Οὐκ ἀκουσόμεσθα δῆτα."]},{"id":"ach-sp-0114","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Δεινὰ τἄρα πείσομαι."]},{"id":"ach-sp-0115","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Ἐξολοίμην, ἢν ἀκούσω."]},{"id":"ach-sp-0116","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μηδαμῶς, ὦχαρνικοί."]},{"id":"ach-sp-0117","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Ὡς τεθνήξων ἴσθι νυνί."]},{"id":"ach-sp-0118","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Δήξομἄρ' ὑμᾶς ἐγώ.","Ἀνταποκτενῶ γὰρ ὑμῶν τῶν φίλων τοὺς φιλτάτους·","ὡς ἔχω γ' ὑμῶν ὁμήρους, οὓς ἀποσφάξω λαβών."]},{"id":"ach-sp-0119","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Εἰπέ μοι, τί τοῦτ' ἀπειλεῖ τοὔπος, ἄνδρες δημόται,","τοῖς Ἀχαρνικοῖσιν ἡμῖν; Μῶν ἔχει του παιδίον","τῶν παρόντων ἔνδον εἵρξας; Ἢ 'πὶ τῷ θρασύνεται;"]},{"id":"ach-sp-0120","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Βάλλετ', εἰ βούλεσθ'· ἐγὼ γὰρ τουτονὶ διαφθερῶ.","Εἴσομαι δ' ὑμῶν τάχ' ὅστις ἀνθράκων τι κήδεται."]},{"id":"ach-sp-0121","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Ὡς ἀπωλόμεσθ'· ὁ λάρκος δημότης ὅδ' ἔστ' ἐμός.","Ἀλλὰ μὴ δράσῃς ὃ μέλλεις, μηδαμῶς, ὢ μηδαμῶς."]},{"id":"ach-sp-0122","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὡς ἀποκτενῶ· κέκραχθ'· ἐγὼ γὰρ οὐκ ἀκούσομαι."]},{"id":"ach-sp-0123","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Ἀπολεῖς ἄρ' ὁμήλικα τόνδε φιλανθρακέα;"]},{"id":"ach-sp-0124","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐδ' ἐμοῦ λέγοντος ὑμεῖς ἀρτίως ἠκούσατε."]},{"id":"ach-sp-0125","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Ἀλλὰ νυνὶ λέγ', ὅ τι σοι δοκεῖ, τόν τε Λακε-","δαιμόνιον αὐτόθεν ὅτῳ τρόπῳ σοὐστὶ φίλος·","ὡς τόδε τὸ λαρκίδιον οὐ προδώσω ποτέ."]},{"id":"ach-sp-0126","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τοὺς λίθους νύν μοι χαμᾶζε πρῶτον ἐξεράσατε."]},{"id":"ach-sp-0127","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Οὑτοιί σοι χαμαί, καὶ σὺ κατάθου πάλιν τὸ ξίφος."]},{"id":"ach-sp-0128","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' ὅπως μὴ 'ν τοῖς τρίβωσιν ἐγκάθηνταί που λίθοι."]},{"id":"ach-sp-0129","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Ἐκσέσεισται χαμᾶζ'. Οὐχ ὁρᾷς σειόμενον;","Ἀλλὰ μή μοι πρόφασιν, ἀλλὰ κατάθου τὸ βέλος.","Ὡς ὅδε γε σειστὸς ἅμα τῇ στροφῇ γίγνεται."]},{"id":"ach-sp-0130","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐμέλλετ' ἆρ' ἅπαντες ἀνασείσειν βοήν,","ὀλίγου τ' ἀπέθανον ἄνθρακες Παρνήσσιοι,","καὶ ταῦτα διὰ τὴν ἀτοπίαν τῶν δημοτῶν.","Ὑπὸ τοῦ δέους δὲ τῆς μαρίλης μοι συχνὴν","ὁ λάρκος ἐνετίλησεν ὥσπερ σηπία.","Δενὸν γὰρ οὕτως ὀμφακίαν πεφυκέναι","τὸν θυμὸν ἀνδρῶν ὥστε βάλλειν καὶ βοᾶν","ἐθέλειν τ' ἀκοῦσαι μηδὲν ἴσον ἴσῳ φέρον,","ἐμοῦ 'θέλοντος ὑπὲρ ἐπιξήνου λέγειν","ὑπὲρ Λακεδαιμονίων ἅπανθ' ὅσ' ἂν λέγω·","καίτοι φιλῶ γε τὴν ἐμὴν ψυχὴν ἐγώ."]},{"id":"ach-sp-0131","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Τί οὖν ‹οὐ› λέγεις, ἐπίξηνον ἐξενεγκὼν θύραζ',","ὅ τι ποτ', ὦ σχέτλιε, τὸ μέγα τοῦτ' ἔχεις;","Πάνυ γὰρ ἐμέ γε πόθος ὅ τι φρονεῖς ἔχει.","Ἀλλ' ᾗπερ αὐτὸς τὴν δίκην διωρίσω,","εὶς δεῦρο τοὐπίξηνον ἐγχείρει λέγειν."]},{"id":"ach-sp-0132","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἰδοὺ θέασαι, τὸ μὲν ἐπίξηνον τοδί,","ὁ δ' ἀνὴρ ὁ λέξων οὑτοσὶ τυννουτοσί.","Ἀμέλει μὰ τὸν Δί' οὐκ ἐνασπιδώσομαι,","λέξω δ' ὑπὲρ Λακεδαιμονίων ἃ 'μοὶ δοκεῖ.","Καίτοι δέδοικα πολλά· τούς τε γὰρ τρόπους","τοὺς τῶν ἀγροίκων οἶδα χαίροντας σφόδρα,","ἐάν τις αὐτοὺς εὐλογῇ καὶ τὴν πόλιν","ἀνὴρ ἀλαζὼν καὶ δίκαια κἄδικα·","κἀνταῦθα λανθάνουσ' ἀπεμπολώμενοι·","τῶν τ' αὖ γερόντων οἶδα τὰς ψυχὰς ὅτι","οὐδὲν βλέπουσιν ἄλλο πλὴν ψηφηδακεῖν.","Αὐτός τ' ἐμαυτὸν ὑπὸ Κλέωνος ἅπαθον","ἐπίσταμαι διὰ τὴν πέρυσι κωμῳδίαν.","Εἰσελκύσας γάρ μ' εἰς τὸ βουλευτήριον","διέβαλλε καὶ ψευδῆ κατεγλώττιζέ μου","κἀκυκλοβόρει κἄπλυνεν, ὥστ' ὀλίγου πάνυ","ἀπωλόμην μολυνοπραγμονούμενος.","Νῦν οὖν με πρῶτον πρὶν λέγειν ἐάσατε","ἐνσκευάσασθαί μ' οἷον ἀθλιώτατον."]},{"id":"ach-sp-0133","scene":"Coro 1","section_id":"ach-div-002","speaker":"Coro","speaker_ref":"#coro","lines":["Τί ταῦτα στρέφει τεχνάζεις τε καὶ πορίζει τριβάς;","Λαβὲ δ' ἐμοῦ γ' ἕνεκα παρ' Ἱερωνύμου","σκοτοδασυπυκνότριχά τιν' Ἄιδος κυνῆν,","εἶτ' ἐξάνοιγε μηχανὰς τὰς Σισύφου·","ὡς σκῆψιν ἁγὼν οὗτος οὐκ εἰσδέξεται."]},{"id":"ach-sp-0134","scene":"Coro 1","section_id":"ach-div-002","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὥρα 'στὶν ἆρα καρτερὰν ψυχὴν λαβεῖν·","καί μοι βαδιστέ' ἐστὶν ὡς Εὐριπίδην.","Παῖ παῖ."]},{"id":"ach-sp-0135","scene":"2","section_id":"ach-div-011","speaker":"Servo","speaker_ref":"#servo","lines":["Τίς οὗτος;"]},{"id":"ach-sp-0136","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἔνδον ἔστ' Εὐριπίδης;"]},{"id":"ach-sp-0137","scene":"2","section_id":"ach-div-011","speaker":"Servo","speaker_ref":"#servo","lines":["Οὐκ ἔνδον ἔνδον ἐστίν, εἰ γνώμην ἔχεις."]},{"id":"ach-sp-0138","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Πῶς ἔνδον, εἶτ' οὐκ ἔνδον;"]},{"id":"ach-sp-0139","scene":"2","section_id":"ach-div-011","speaker":"Servo","speaker_ref":"#servo","lines":["Ὀρθῶς, ὦ γέρον.","Ὁ νοῦς μὲν ἔξω ξυλλέγων ἐπύλλια","οὐκ ἔνδον, αὐτὸς δ' ἔνδον ἀναβάδην ποεῖ","τραγῳδίαν."]},{"id":"ach-sp-0140","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ τρισμακάρι' Εὐριπίδη,","ὅθ' ὁ δοῦλος οὑτωσὶ σοφῶς ὑποκρίνεται.","Ἐκκάλεσον αὐτόν."]},{"id":"ach-sp-0141","scene":"2","section_id":"ach-div-011","speaker":"Servo","speaker_ref":"#servo","lines":["Ἀλλ' ἀδύνατον."]},{"id":"ach-sp-0142","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' ὅμως·","οὐ γὰρ ἂν ἀπέλθοιμ'. ‑ Ἀλλὰ κόψω τὴν θύραν.","Εὐριπίδη, Εὐριπίδιον,","ὑπάκουσον, εἴπερ πώποτ' ἀνθρώπων τινί·","Δικαιόπολις καλῶ σ' ὁ Χολλῄδης ἐγώ"]},{"id":"ach-sp-0143","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἀλλ' οὐ σχολή."]},{"id":"ach-sp-0144","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' ἐκκυκλήθητ'."]},{"id":"ach-sp-0145","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἀλλ' ἀδύνατον."]},{"id":"ach-sp-0146","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' ὅμως."]},{"id":"ach-sp-0147","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἀλλ' ἐκκυκλήσομαι· καταβαίνειν δ' οὐ σχολή."]},{"id":"ach-sp-0148","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Εὐριπίδη."]},{"id":"ach-sp-0149","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Τί λέλακας;"]},{"id":"ach-sp-0150","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀναβάδην ποεῖς,","ἐξὸν καταβάδην. Οὐκ ἐτὸς χωλοὺς ποεῖς.","Ἀτὰρ τί τὰ ῥάκι' ἐκ τραγῳδίας ἔχεις,","ἐσθῆτ' ἐλεινήν; Οὐκ ἐτὸς πτωχοὺς ποεῖς.","Ἀλλ' ἀντιβολῶ πρὸς τῶν γονάτων σ', Εὐριπίδη,","δός μοι ῥάκιόν τι τοῦ παλαιοῦ δράματος.","Δεῖ γάρ με λέξαι τῷ χορῷ ῥῆσιν μακράν·","αὕτη δὲ θάνατον, ἢν κακῶς λέξω, φέρει."]},{"id":"ach-sp-0151","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Τὰ ποῖα τρύχη; Μῶν ἐν οἷς Οἰνεὺς ὁδὶ","ὁ δύσποτμος γεραιὸς ἠγωνίζετο;"]},{"id":"ach-sp-0152","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐκ Οἰνέως ἦν, ἀλλ' ἔτ' ἀθλιωτέρου."]},{"id":"ach-sp-0153","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Τὰ τοῦ τυφλοῦ Φοίνικος;"]},{"id":"ach-sp-0154","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐ Φοίνικος, οὔ·","ἀλλ' ἕτερος ἦν Φοίνικος ἀθλιώτερος"]},{"id":"ach-sp-0155","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ποίας ποθ' ἁνὴρ λακίδας αἰτεῖται πέπλων,","Ἀλλ' ἦ Φιλοκτήτου τὰ τοῦ πτωχοῦ λέγεις;"]},{"id":"ach-sp-0156","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὔκ, ἀλλὰ τούτου πολὺ πολὺ πτωχιστέρου."]},{"id":"ach-sp-0157","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἀλλ' ἦ τὰ δυσπινῆ θέλεις πεπλώματα,","ἃ Βελλεροφόντης εἶχ' ὁ χωλὸς οὑτοσί;"]},{"id":"ach-sp-0158","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐ Βελλεροφόντης· ἀλλὰ κἀκεῖνος μὲν ἦν","χωλός, προσαιτῶν, στωμύλος, δεινὸς λέγειν."]},{"id":"ach-sp-0159","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Οἶδ' ἄνδρα, Μυσὸν Τήλεφον."]},{"id":"ach-sp-0160","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ναί, Τήλεφον","τούτου δός, ἀντιβολῶ σέ, μοι τὰ σπάργανα."]},{"id":"ach-sp-0161","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ὦ παῖ, δὸς αὐτῷ Τηλέφου ῥακώματα.","Κεῖται δ' ἄνωθεν τῶν Θυεστείων ῥακῶν","μεταξὺ τῶν Ἰνοῦς. Ἰδού, ταυτὶ λαβέ."]},{"id":"ach-sp-0162","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ Ζεῦ διόπτα καὶ κατόπτα πανταχῇ,","ἐνσκευάσασθαί μ' οἷον ἀθλιώτατον.","Εὐριπίδη, 'πειδήπερ ἐχαρίσω ταδί,","κἀκεῖνά μοι δὸς τἀκόλουθα τῶν ῥακῶν,","τὸ πιλίδιον περὶ τὴν κεφαλὴν τὸ Μύσιον.","Δεῖ γάρ με δόξαι πτωχὸν εἶναι τήμερον,","εἶναι μὲν ὅσπερ εἰμί, φαίνεσθαι δὲ μή·","τοὺς μὲν θεατὰς εἰδέναι μ' ὅς εἰμ' ἐγώ,","τοὺς δ' αὖ χορευτὰς ἠλιθίους παρεστάναι,","ὅπως ἂν αὐτοὺς ῥηματίοις σκιμαλίσω."]},{"id":"ach-sp-0163","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ὦ τρισμακάρι' Εὐριπίδη,","ὅθ' ὁ δοῦλος οὑτωσὶ σοφῶς ὑποκρίνεται.","Ἐκκάλεσον αὐτόν."]},{"id":"ach-sp-0164","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ τρισμακάρι' Εὐριπίδη,","ὅθ' ὁ δοῦλος οὑτωσὶ σοφῶς ὑποκρίνεται.","Ἐκκάλεσον αὐτόν."]},{"id":"ach-sp-0165","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Δώσω· πυκνῇ γὰρ λεπτὰ μηχανᾷ φρενί."]},{"id":"ach-sp-0166","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Εὐδαιμονοίης ‑ Τηλέφῳ δ' ἁγὼ φρονῶ.","Εὖ γ'· οἷον ἤδη ῥηματίων ἐμπίμπλαμαι.","Ἀτὰρ δέομαί γε πτωχικοῦ βακτηρίου."]},{"id":"ach-sp-0167","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Τουτὶ λαβὼν ἄπελθε λαΐνων σταθμῶν."]},{"id":"ach-sp-0168","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ θύμ', ‑ ὁρᾷς γὰρ ὡς ἀπωθοῦμαι δόμων,","πολλῶν δεόμενος σκευαρίων, ‑ νῦν δὴ γενοῦ","γλίσχρος, προσαιτῶν, λιπαρῶν. Εὐριπίδη,","δός μοι σπυρίδιον διακεκαυμένον λύχνῳ."]},{"id":"ach-sp-0169","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Τί δ', ὦ τάλας, σε τοῦδ' ἔχει πλέκους χρέος;"]},{"id":"ach-sp-0170","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Χρέος μὲν οὐδέν, βούλομαι δ' ὅμως λαβεῖν."]},{"id":"ach-sp-0171","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Λυπηρὸς ἴσθ' ὢν κἀποχώρησον δόμων."]},{"id":"ach-sp-0172","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Φεῦ.","Εὐδαιμονοίης, ὥσπερ ἡ μήτηρ ποτέ."]},{"id":"ach-sp-0173","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἄπελθέ νύν μοι."]},{"id":"ach-sp-0174","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μἀλλά μοι δὸς ἓν μόνον,","κοτυλίσκιον τὸ χεῖλος ἀποκεκρουμένον."]},{"id":"ach-sp-0175","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Φθείρου λαβὼν τόδ'· ἴσθ' ὀχληρὸς ὢν δόμοις."]},{"id":"ach-sp-0176","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὔτοι μὰ Δί' οἶσθ' οἷ' αὐτὸς ἐργάζει κακά.","Ἀλλ', ὦ γλυκύτατ' Εὐριπίδη, τουτὶ μόνον,","δός μοι χυτρίδιον σπογγίῳ βεβυσμένον."]},{"id":"ach-sp-0177","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἄνθρωπ', ἀφαιρήσει με τὴν τραγῳδίαν.","Ἄπελθε ταυτηνὶ λαβών."]},{"id":"ach-sp-0178","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀπέρχομαι.","Καίτοι τί δράσω; Δεῖ γὰρ ἑνὸς οὗ μὴ τυχὼν","ἀπόλωλ'. Ἄκουσον, ὦ γλυκύτατ' Εὐριπίδη·","τουτὶ λαβὼν ἄπειμι κοὐ πρόσειμ' ἔτι·","εἰς τὸ σπυρίδιον ἰσχνά μοι φυλλεῖα δός."]},{"id":"ach-sp-0179","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἀπολεῖς μ'. Ἰδού σοι. Φροῦδά μοι τὰ δράματα."]},{"id":"ach-sp-0180","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' οὐκέτ', ἀλλ' ἄπειμι. Καὶ γάρ εἰμ' ἄγαν","ὀχληρός, οὐ δοκῶν με κοιράνους στυγεῖν.","Οἴμοι κακοδαίμων, ὡς ἀπόλωλ'. Ἐπελαθόμην","ἐν ᾧπέρ ἐστι πάντα μοι τὰ πράγματα.","Εὐριπίδιον ὦ γλυκύτατον καὶ φίλτατον,","κάκιστ' ἀπολοίμην, εἴ τί σ' αἰτήσαιμ' ἔτι,","πλὴν ἓν μόνον, τουτὶ μόνον, τουτὶ μόνον,","σκάνδικά μοι δὸς μητρόθεν δεδεγμένος."]},{"id":"ach-sp-0181","scene":"2","section_id":"ach-div-011","speaker":"Euripide","speaker_ref":"#euripide","lines":["Ἁνὴρ ὑβρίζει· κλῇε πηκτὰ δωμάτων."]},{"id":"ach-sp-0182","scene":"2","section_id":"ach-div-011","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ θύμ', ἄνευ σκάνδικος ἐμπορευτέα.","Ἆρ' οἶσθ' ὅσον τὸν ἀγῶν' ἀγωνιεῖ τάχα,","μέλλων ὑπὲρ Λακεδαιμονίων ἀνδρῶν λέγειν;","Πρόβαινέ νυν, ὦ θυμέ· γραμμὴ δ' αὑτηί.","Ἕστηκας; Οὐκ εἶ καταπιὼν Εὐριπίδην;","Ἐπῄνεσ'· ἄγε νυν, ὦ τάλαινα καρδία,","ἄπελθ' ἐκεῖσε, κᾆτα τὴν κεφαλὴν ἐκεῖ","παράσχες εἰποῦσ' ἅττ' ἂν αὐτῇ σοὶ δοκῇ.","Τόλμησον, ἴθι, χώρησον· ἄγαμαι καρδίας."]},{"id":"ach-sp-0183","scene":"2","section_id":"ach-div-011","speaker":"Coro","speaker_ref":"#coro","lines":["Τί δράσεις; Τί φήσεις; ‹Εὖ› ἴσθι νυν","ἀναίσχυντος ὢν σιδηροῦς τ' ἀνήρ,","ὅστις παρασχὼν τῇ πόλει τὸν αὐχένα","ἅπασι μέλλεις εἷς λέγειν τἀναντία.","Ἁνὴρ οὐ τρέμει τὸ πρᾶγμ'. Εἶά νυν,","ἐπειδήπερ αὐτὸς αἱρεῖ, λέγε."]},{"id":"ach-sp-0184","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μή μοι φθονήσητ', ἄνδρες οἱ θεώμενοι,","εἰ πτωχὸς ὢν ἔπειτ' ἐν Ἀθηναίοις λέγειν","μέλλω περὶ τῆς πόλεως, τρυγῳδίαν ποιῶν.","Τὸ γὰρ δίκαιον οἶδε καὶ τρυγῳδία.","Ἐγὼ δὲ λέξω δεινὰ μέν, δίκαια δέ.","Οὐ γάρ με νῦν γε διαβαλεῖ Κλέων ὅτι","ξένων παρόντων τὴν πόλιν κακῶς λέγω.","Αὐτοὶ γάρ ἐσμεν οὑπὶ Ληναίῳ τ' ἀγών,","κοὔπω ξένοι πάρεισιν· οὔτε γὰρ φόροι","ἥκουσιν οὔτ' ἐκ τῶν πόλεων οἱ ξύμμαχοι·","ἀλλ' ἐσμὲν αὐτοὶ νῦν γε περιεπτισμένοι·","τοὺς γὰρ μετοίκους ἄχυρα τῶν ἀστῶν λέγω.","Ἐγὼ δὲ μισῶ μὲν Λακεδαιμονίους σφόδρα,","καὐτοῖς ὁ Ποσειδῶν, οὑπὶ Ταινάρῳ θεός,","σείσας ἅπασιν ἐμβάλοι τὰς οἰκίας·","κἀμοὶ γάρ ἐστι τἀμπέλια κεκομμένα.","Ἀτάρ, φίλοι γὰρ οἱ παρόντες ἐν λόγῳ,","τί ταῦτα τοὺς Λάκωνας αἰτιώμεθα;","Ἡμῶν γὰρ ἄνδρες, ‑ οὐχὶ τὴν πόλιν λέγω.","μέμνησθε τοῦθ', ὅτι οὐχὶ τὴν πόλιν λέγω, ‑","ἀλλ' ἀνδράρια μοχθηρά, παρακεκομμένα,","ἄτιμα καὶ παράσημα καὶ παράξενα,","ἐσυκοφάντει· \"Μεγαρέων τὰ χλανίσκια.\"","Κεἴ που σίκυον ἴδοιεν ἢ λαγῴδιον","ἢ χοιρίδιον ἢ σκόροδον ἢ χόνδρους ἅλας,","ταῦτ' ἦν Μεγαρικὰ κἀπέπρατ' αὐθημερόν.","Καὶ ταῦτα μὲν δὴ σμικρὰ κἀπιχώρια,","πόρνην δὲ Σιμαίθαν ἰόντες Μεγαράδε","νεανίαι 'κκλέπτουσι μεθυσοκότταβοι·","κᾆθ' οἱ Μεγαρῆς ὀδύναις πεφυσιγγωμένοι","ἀντεξέκλεψαν Ἀσπασίας πόρνα δύο·","κἀντεῦθεν ἀρχὴ τοῦ πολέμου κατερράγη","Ἕλλησι πᾶσιν ἐκ τριῶν λαικαστριῶν.","Ἐντεῦθεν ὀργῇ Περικλέης οὑλύμπιος","ἤστραπτ', ἐβρόντα, ξυνεκύκα τὴν Ἑλλάδα,","ἐτίθει νόμους ὥσπερ σκόλια γεγραμμένους,","ὡς χρὴ Μεγαρέας μήτε γῇ μήτ' ἐν ἀγορᾷ","μήτ' ἐν θαλάττῃ μήτ' ἐν ἠπείρῳ μένειν.","Ἐντεῦθεν οἱ Μεγαρῆς, ὅτε δὴ 'πείνων βάδην,","Λακεδαιμονίων ἐδέοντο τὸ ψήφισμ' ὅπως","μεταστραφείη τὸ διὰ τὰς λαικαστρίας·","οὐκ ἠθέλομεν δ' ἡμεῖς δεομένων πολλάκις.","Κἀντεῦθεν ἤδη πάταγος ἦν τῶν ἀσπίδων.","Ἐρεῖ τις· \"Οὐ χρῆν·\" ἀλλὰ τί ἐχρῆν, εἴπατε.","Φέρ', εἰ Λακεδαιμονίων τις ἐκπλεύσας σκάφει","ἀπέδοτο φήνας κυνίδιον Σεριφίων,","καθῆσθ' ἂν ἐν δόμοισιν; Ἦ πολλοῦ γε δεῖ.","καὶ κάρτα μέντἂν εὐθέως καθείλκετε","τριακοσίας ναῦς, ἦν δ' ἂν ἡ πόλις πλέα","θορύβου στρατιωτῶν, περὶ τριηράρχου βοῆς,","μισθοῦ διδομένου, παλλαδίων χρυσουμένων,","στοᾶς στεναχούσης, σιτίων μετρουμένων,","ἀσκῶν, τροπωτήρων, κάδους ὠνουμένων,","σκορόδων, ἐλαῶν, κρομμύων ἐν δικτύοις,","στεφάνων, τριχίδων, αὐλητρίδων, ὑπωπίων·","τὸ νεώριον δ' αὖ κωπέων πλατουμένων,","τύλων ψοφούντων, θαλαμιῶν τροπουμένων,","αὐλῶν, κελευστῶν, νιγλάρων, συριγμάτων.","Ταῦτ' οἶδ' ὅτι ἂν ἐδρᾶτε· τὸν δὲ Τήλεφον","οὐκ οἰόμεσθα; Νοῦς ἄρ' ἡμῖν οὐκ ἔνι."]},{"id":"ach-sp-0185","scene":"3","section_id":"ach-div-012","speaker":"Semicoro A","speaker_ref":"#semicoro-a","lines":["Ἄληθες, ὦπίτριπτε καὶ μιαρώτατε;","ταυτὶ σὺ τολμᾷς πτωχὸς ὢν ἡμᾶς λέγειν,","καὶ συκοφάντης εἴ τις ἦν ὠνείδισας;"]},{"id":"ach-sp-0186","scene":"3","section_id":"ach-div-012","speaker":"Semicoro B","speaker_ref":"#semicoro-b","lines":["Νὴ τὸν Ποσειδῶ, καὶ λέγει γ' ἅπερ λέγει","δίκαια πάντα κοὐδὲν αὐτῶν ψεύδεται."]},{"id":"ach-sp-0187","scene":"3","section_id":"ach-div-012","speaker":"Semicoro A","speaker_ref":"#semicoro-a","lines":["Εἶτ' εἰ δίκαια, τοῦτον εἰπεῖν αὔτ' ἐχρῆν;","Ἀλλ' οὔτι χαίρων ταῦτα τολμήσει λέγειν."]},{"id":"ach-sp-0188","scene":"3","section_id":"ach-div-012","speaker":"Semicoro B","speaker_ref":"#semicoro-b","lines":["Οὗτος σύ, ποῖ θεῖς; Οὐ μενεῖς; Ὡς εἰ θενεῖς","τὸν ἄνδρα τοῦτον, αὐτὸς ἀρθήσει τάχα."]},{"id":"ach-sp-0189","scene":"3","section_id":"ach-div-012","speaker":"Semicoro A","speaker_ref":"#semicoro-a","lines":["Ἰὼ Λάμαχ', ὦ βλέπων ἀστραπάς,","βοήθησον, ὦ γοργολόφα, φανείς,","ἰὼ Λάμαχ', ὦ φίλ', ὦ φυλέτα·","εἴτ' ἔστι ταξίαρχος ἢ στρατηγὸς ἢ","τειχομάχας ἀνήρ, βοηθησάτω","τις ἁνύσας· ἐγὼ γὰρ ἔχομαι μέσος."]},{"id":"ach-sp-0190","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Πόθεν βοῆς ἤκουσα πολεμιστηρίας;","Ποῖ χρὴ βοηθεῖν; Ποῖ κυδοιμὸν ἐμβαλεῖν;","Τίς Γοργόν' ἐξήγειρεν ἐκ τοῦ σάγματος;"]},{"id":"ach-sp-0191","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ Λάμαχ', ἥρως τῶν λόφων καὶ τῶν λόχων."]},{"id":"ach-sp-0192","scene":"3","section_id":"ach-div-012","speaker":"Coro","speaker_ref":"#coro","lines":["Ὦ Λάμαχ', οὐ γὰρ οὗτος ἅνθρωπος πάλαι","ἅπασαν ἡμῶν τὴν πόλιν κακορροθεῖ;"]},{"id":"ach-sp-0193","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Οὗτος, σὺ τολμᾷς πτωχὸς ὢν λέγειν τάδε;"]},{"id":"ach-sp-0194","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ Λάμαχ' ἥρως, ἀλλὰ συγγνώμην ἔχε,","εἰ πτωχὸς ὢν εἶπόν τι κἀστωμυλάμην."]},{"id":"ach-sp-0195","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τί δ' εἶπας ἡμᾶς; Οὐκ ἐρεῖς;"]},{"id":"ach-sp-0196","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐκ οἶδά πω·","ὑπὸ τοῦ δέους γὰρ τῶν ὅπλων εἰλιγγιῶ.","Ἀλλ', ἀντιβολῶ σ', ἀπένεγκέ μου τὴν μορμόνα."]},{"id":"ach-sp-0197","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἰδού."]},{"id":"ach-sp-0198","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Παράθες νυν ὑπτίαν αὐτὴν ἐμοί."]},{"id":"ach-sp-0199","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Κεῖται."]},{"id":"ach-sp-0200","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Φέρε νυν ἀπὸ τοῦ κράνους μοι τὸ πτερόν."]},{"id":"ach-sp-0201","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τουτὶ πτίλον σοι."]},{"id":"ach-sp-0202","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τῆς κεφαλῆς νύν μου λαβοῦ,","ἵν' ἐξεμέσω· βδελύττομαι γὰρ τοὺς λόφους."]},{"id":"ach-sp-0203","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Οὗτος, τί δράσεις; Τῷ πτίλῳ μέλλεις ἐμεῖν;","Πτίλον γάρ ἐστιν ‑"]},{"id":"ach-sp-0204","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Εἰπέ μοι, τίνος ποτὲ","ὄρνιθός ἐστιν; Ἆρα κομπολακύθου;"]},{"id":"ach-sp-0205","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Οἴμ' ὡς τεθνήξεις."]},{"id":"ach-sp-0206","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μηδαμῶς, ὦ Λάμαχε","οὐ γὰρ κατ' ἰσχύν ἐστιν· εἰ δ' ἰσχυρὸς εἶ,","τί μ' οὐκ ἀπεψώλησας; Εὔοπλος γὰρ εἶ."]},{"id":"ach-sp-0207","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ταυτὶ λέγεις σὺ τὸν στρατηγὸν πτωχὸς ὤν,"]},{"id":"ach-sp-0208","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐγὼ γάρ εἰμι πτωχός;"]},{"id":"ach-sp-0209","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἀλλὰ τίς γὰρ εἶ;"]},{"id":"ach-sp-0210","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὅστις; πολίτης χρηστός, οὐ σπουδαρχίδης,","ἀλλ' ἐξ ὅτουπερ ὁ πόλεμος, στρατωνίδης,","σὺ δ' ἐξ ὅτουπερ ὁ πόλεμος, μισθαρχίδης"]},{"id":"ach-sp-0211","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἐχειροτόνησαν γάρ με ‑"]},{"id":"ach-sp-0212","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["κόκκυγές γε τρεῖς.","Ταῦτ' οὖν ἐγὼ βδελυττόμενος ἐσπεισάμην,","ὁρῶν πολιοὺς μὲν ἄνδρας ἐν ταῖς τάξεσιν,","νεανίας δ' οἵους σὺ διαδεδρακότας,","τοὺς μὲν ἐπὶ Θρᾴκης μισθοφοροῦντας τρεῖς δραχμάς,","Τεισαμενοφαινίππους πανουργιππαρχίδας,","ἑτέρους δὲ παρὰ Χάρητι, τοὺς δ' ἐν Χάοσιν,","Γερητοθεοδώρους Διομειαλαζόνας,","τοὺς δ' ἐν Καμαρίνῃ κἀν Γέλᾳ κἀν Καταγέλᾳ."]},{"id":"ach-sp-0213","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἐχειροτονήθησαν γάρ."]},{"id":"ach-sp-0214","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Αἴτιον δὲ τί","ὑμᾶς μὲν ἀεὶ μισθοφορεῖν ἁμῃγέπῃ,","τωνδὶ δὲ μηδέν'; Ἐτεόν, ὦ Μαριλάδη,","ἤδη πεπρέσβευκας σὺ πολιὸς ὢν ἕν; Ἤν,","ἀνένευσε· καίτοι γ' ἐστὶ σώφρων κἀργάτης.","Τί δ' Ἀνθράκυλλος ἢ Εὐφορίδης ἢ Πρινίδης;","Εἶδέν τις ὑμῶν τἀκβάταν' ἢ τοὺς Χάονας;","Οὔ φασιν. Ἀλλ' ὁ Κοισύρας καὶ Λάμαχος,","οἷς ὑπ' ἐράνων τε καὶ χρεῶν πρώην ποτέ,","ὥσπερ ἀπόνιπτρον ἐκχέοντες ἑσπέρας,","ἅπαντες ἐξίστω παρῄνουν οἱ φίλοι."]},{"id":"ach-sp-0215","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ὦ δημοκρατία, ταῦτα δῆτ' ἀνασχετά;"]},{"id":"ach-sp-0216","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐ δῆτ', ἐὰν μὴ μισθοφορῇ γε Λάμαχος."]},{"id":"ach-sp-0217","scene":"3","section_id":"ach-div-012","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἀλλ' οὖν ἐγὼ μὲν πᾶσι Πελοποννησίοις","ἀεὶ πολεμήσω καὶ ταράξω πανταχῇ,","καὶ ναυσὶ καὶ πεζοῖσι, κατὰ τὸ καρτερόν."]},{"id":"ach-sp-0218","scene":"3","section_id":"ach-div-012","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐγὼ δὲ κηρύττω γε Πελοποννησίοις","ἅπασι καὶ Μεγαρεῦσι καὶ Βοιωτίοις","πωλεῖν ἀγοράζειν πρὸς ἐμέ, Λαμάχῳ δὲ μή."]},{"id":"ach-sp-0219","scene":"Coro 2","section_id":"ach-div-013","speaker":"Coro","speaker_ref":"#coro","lines":["Ἁνὴρ νικᾷ τοῖσι λόγοισιν, καὶ τὸν δῆμον μεταπείθει","περὶ τῶν σπονδῶν. Ἀλλ' ἀποδύντες τοῖς ἀναπαίστοις ἐπίωμεν.","Ἐξ οὗ γε χοροῖσιν ἐφέστηκεν τρυγικοῖς ὁ διδάσκαλος ἡμῶν,","οὔπω παρέβη πρὸς τὸ θέατρον λέξων ὡς δεξιός ἐστιν·","διαβαλλόμενος δ' ὑπὸ τῶν ἐχθρῶν ἐν Ἀθηναίοις ταχυβούλοις,","ὡς κωμῳδεῖ τὴν πόλιν ἡμῶν καὶ τὸν δῆμον καθυβρίζει,","ἀποκρίνασθαι δεῖται νυνὶ πρὸς Ἀθηναίους μεταβούλους.","Φησὶν δ' εἶναι πολλῶν ἀγαθῶν αἴτιος ὑμῖν ὁ ποητής,","παύσας ὑμᾶς ξενικοῖσι λόγοις μὴ λίαν ἐξαπατᾶσθαι,","μήθ' ἥδεσθαι θωπευομένους, μήτ' εἶναι χαυνοπολίτας.","Πρότερον δ' ὑμᾶς ἀπὸ τῶν πόλεων οἱ πρέσβεις ἐξαπατῶντες","πρῶτον μὲν ἰοστεφάνους ἐκάλουν· κἀπειδὴ τοῦτό τις εἴποι,","εὐθὺς διὰ τοὺς στεφάνους ἐπ' ἄκρων τῶν πυγιδίων ἐκάθησθε.","Εἰ δέ τις ὑμᾶς ὑποθωπεύσας λιπαρὰς καλέσειεν Ἀθήνας,","ηὕρετο πᾶν ἂν διὰ τὰς λιπαράς, ἀφύων τιμὴν περιάψας.","Ταῦτα ποήσας πολλῶν ἀγαθῶν αἴτιος ὑμῖν γεγένηται,","καὶ τοὺς δήμους ἐν ταῖς πόλεσιν δείξας ὡς δημοκρατοῦνται.","Τοιγάρτοι νῦν οὑκ τῶν πόλεων τὸν φόρον ὑμῖν ἀπάγοντες","ἥξουσιν ἰδεῖν ἐπιθυμοῦντες τὸν ποιητὴν τὸν ἄριστον,","ὅστις παρεκινδύνευσ' ἐν Ἀθηναίοις εἰπεῖν τὰ δίκαια.","Οὕτω δ' αὐτοῦ περὶ τῆς τόλμης ἤδη πόρρω κλέος ἥκει,","ὅτε καὶ βασιλεὺς Λακεδαιμονίων τὴν πρεσβείαν βασανίζων","ἠρώτησεν πρῶτα μὲν αὐτοὺς πότεροι ταῖς ναυσὶ κρατοῦσιν,","εἶτα δὲ τοῦτον τὸν ποιητὴν ποτέρους εἴποι κακὰ πολλά·","τούτους γὰρ ἔφη τοὺς ἀνθρώπους πολὺ βελτίους γεγενῆσθαι","καὶ τῷ πολέμῳ πολὺ νικήσειν τοῦτον ξύμβουλον ἔχοντας.","Διὰ ταῦθ' ὑμᾶς Λακεδαιμόνιοι τὴν εἰρήνην προκαλοῦνται","καὶ τὴν Αἴγιναν ἀπαιτοῦσιν· καὶ τῆς νήσου μὲν ἐκείνης","οὐ φροντίζουσ', ἀλλ' ἵνα τοῦτον τὸν ποιητὴν ἀφέλωνται.","Ἀλλ' ὑμεῖς τοι μή ποτ' ἀφῆσθ'· ὡς κωμῳδήσει τὰ δίκαια.","Φησὶν δ' ὑμᾶς πολλὰ διδάξειν ἀγάθ', ὥστ' εὐδαίμονας εἶναι,","οὐ θωπεύων οὐδ' ὑποτείνων μισθοὺς οὐδ' ἐξαπατύλλων,","οὐδὲ πανουργῶν οὐδὲ κατάρδων, ἀλλὰ τὰ βέλτιστα διδάσκων.","Πρὸς ταῦτα Κλέων καὶ παλαμάσθω","καὶ πᾶν ἐπ' ἐμοὶ τεκταινέσθω.","Τὸ γὰρ εὖ μετ' ἐμοῦ καὶ τὸ δίκαιον","ξύμμαχον ἔσται, κοὐ μή ποθ' ἁλῶ","περὶ τὴν πόλιν ὢν ὥσπερ ἐκεῖνος","δειλὸς καὶ λακαταπύγων."]},{"id":"ach-sp-0220","scene":"Coro 2","section_id":"ach-div-013","speaker":"Coro","speaker_ref":"#coro","lines":["Δεῦρο Μοῦσ' ἐλθὲ φλεγυρὰ πυρὸς ἔ-","χουσα μένος ἔντονος Ἀχαρνική.","Οἷον ἐξ ἀνθράκων πρινίνων φέψαλος ἀν-","ήλατ' ἐρεθιζόμενος οὐρίᾳ ῥιπίδι,","ἡνίκ' ἂν ἐπανθρακίδες ὦσι παρακείμεναι,","οἱ δὲ Θασίαν ἀνακυκῶσι λιπαράμπυκα,","οἱ δὲ μάττωσιν, οὕτω σοβαρὸν","ἐλθὲ μέλος εὔτονον, ἀγροικότονον,","ὡς ἐμὲ λαβοῦσα τὸν δημότην.","Οἱ γέροντες οἱ παλαιοὶ μεμφόμεσθα τῇ πόλει","οὐ γὰρ ἀξίως ἐκείνων ὧν ἐναυμαχήσαμεν","γηροβοσκούμεσθ' ὑφ' ὑμῶν, ἀλλὰ δεινὰ πάσχομεν,","οἵτινες γέροντας ἄνδρας ἐμβαλόντες εἰς γραφὰς","ὑπὸ νεανίσκων ἐᾶτε καταγελᾶσθαι ῥητόρων,","οὐδὲν ὄντας, ἀλλὰ κωφοὺς καὶ παρεξηυλημένους,","οἷς Ποσειδῶν ἀσφάλειός ἐστιν ἡ βακτηρία·","τονθορύζοντες δὲ γήρᾳ τῷ λίθῳ προσέσταμεν,","οὐχ ὁρῶντες οὐδὲν εἰ μὴ τῆς δίκης τὴν ἠλύγην.","Ὁ δὲ νεανίας ἑαυτῷ σπουδάσας ξυνηγορεῖν","εἰς τάχος παίει ξυνάπτων στρογγύλοις τοῖς ῥήμασιν","κᾆτ' ἀνελκύσας ἐρωτᾷ σκανδάληθρ' ἱστὰς ἐπῶν","ἄνδρα Τιθωνὸν σπαράττων καὶ ταράττων καὶ κυκῶν.","Ὁ δ' ὑπὸ γήρως μασταρύζει, κᾆτ' ὀφλὼν ἀπέρχεται","εἶτα λύζει καὶ δακρύει καὶ λέγει πρὸς τοὺς φίλους·","\"Οὗ μ' ἐχρῆν σορὸν πρίασθαι τοῦτ' ὀφλὼν ἀπέρχομαι.\""]},{"id":"ach-sp-0221","scene":"Coro 2","section_id":"ach-div-013","speaker":"Coro","speaker_ref":"#coro","lines":["Ταῦτα πῶς εἰκότα, γέροντ' ἀπολέ-","σαι πολιὸν ἄνδρα περὶ κλεψύδραν,","πολλὰ δὴ ξυμπονήσαντα καὶ θερμὸν ἀπο-","μορξάμενον ἀνδρικὸν ἱδρῶτα δὴ καὶ πολύν,","ἄνδρ' ἀγαθὸν ὄντα Μαραθῶνι περὶ τὴν πόλιν;","Εἶτα Μαραθῶνι μὲν ὅτ' ἦμεν, ἐδιώκομεν,","νῦν δ' ὑπ' ἀνδρῶν πονηρῶν σφόδρα δι-","ωκόμεθα, κᾆτα πρὸς ἁλισκόμεθα.","Πρὸς τάδε τίς ἀντερεῖ Μαρψίας;","Τῷ γὰρ εἰκὸς ἄνδρα κυφόν, ἡλίκον Θουκυδίδην,","ἐξολέσθαι συμπλακέντα τῇ Σκυθῶν ἐρημίᾳ,","τῷδε τῷ Κηφισοδήμου, τῷ λάλῳ ξυνηγόρῳ;","Ὥστ' ἐγὼ μὲν ἠλέησα κἀπεμορξάμην ἰδὼν","ἄνδρα πρεσβύτην ὑπ' ἀνδρὸς τοξότου κυκώμενον","ὃς μὰ τὴν Δήμητρ', ἐκεῖνος ἡνίκ' ἦν Θουκυδίδης,","οὐδ' ἂν αὐτὴν τὴν Ἀχαίαν ῥᾳδίως ἠνέσχετο,","ἀλλὰ κατεπάλαισε μέν ‹γ'› ἂν πρῶτον Εὐάθλους δέκα,","κατεβόησε δ' ἂν κεκραγὼς τοξότας τρισχιλίους,","περιετόξευσεν δ' ἂν αὐτοῦ τοῦ πατρὸς τοὺς ξυγγενεῖς.","Ἀλλ' ἐπειδὴ τοὺς γέροντας οὐκ ἐᾶθ' ὕπνου τυχεῖν,","ψηφίσασθε χωρὶς εἶναι τὰς γραφάς, ὅπως ἂν ᾖ","τῷ γέροντι μὲν γέρων καὶ νωδὸς ὁ ξυνήγορος,","τοῖς νέοισι δ' εὐρύπρωκτος καὶ λάλος χὠ Κλεινίου.","Κἀξελαύνειν χρὴ τὸ λοιπόν ‑ κἂν φύγῃ τις ζημιοῦν ‑","τὸν γέροντα τῷ γέροντι, τὸν νέον δὲ τῷ νέῳ."]},{"id":"ach-sp-0222","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὅροι μὲν ἀγορᾶς εἰσιν οἵδε τῆς ἐμῆς.","Ἐνταῦθ' ἀγοράζειν πᾶσι Πελοποννησίοις","ἔξεστι καὶ Μεγαρεῦσι καὶ Βοιωτίοις,","ἐφ' ᾧτε πωλεῖν πρὸς ἐμέ, Λαμάχῳ δὲ μή.","Ἀγορανόμους δὲ τῆς ἀγορᾶς καθίσταμαι","τρεῖς τοὺς λαχόντας τούσδ' ἱμάντας ἐκ Λεπρῶν.","Ἐνταῦθα μήτε συκοφάντης εἰσίτω","μήτ' ἄλλος ὅστις Φασιανός ἐστ' ἀνήρ.","Ἐγὼ δὲ τὴν στήλην καθ' ἣν ἐσπεισάμην","μέτειμ', ἵνα στήσω φανερὰν ἐν τἀγορᾷ."]},{"id":"ach-sp-0223","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ἀγορὰ 'ν Ἀθάναις, χαῖρε, Μεγαρεῦσιν φίλα.","Ἐπόθουν τυ ναὶ τὸν Φίλιον ᾇπερ ματέρα.","Ἀλλ', ὦ πόνηρα κώρι' ἀθλίω πατρός,","ἄμβατε ποττὰν μᾶδδαν, αἴ χ' εὕρητέ πα.","Ἀκούετε δή, ποτέχετ' ἐμὶν τὰν γαστέρα·","πότερα πεπρᾶσθαι χρῄδδετ' ἢ πεινῆν κακῶς;"]},{"id":"ach-sp-0224","scene":"4","section_id":"ach-div-016","speaker":"Ragazza","speaker_ref":"#ragazza","lines":["Πεπρᾶσθαι πεπρᾶσθαι."]},{"id":"ach-sp-0225","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ἐγώνγα καὐτός φαμι. Τίς δ' οὕτως ἄνους","ὃς ὑμέ κα πρίαιτο, φανερὰν ζαμίαν;","Ἀλλ' ἔστι γάρ μοι Μεγαρικά τις μαχανά·","χοίρως γὰρ ὑμὲ σκευάσας φασῶ φέρειν.","Περίθεσθε τάσδε τὰς ὁπλὰς τῶν χοιρίων·","ὅπως δὲ δοξεῖτ' εἶμεν ἐξ ἀγαθᾶς ὑός·","ὡς ναὶ τὸν Ἑρμᾶν, αἴπερ εἱξεῖτ' οἴκαδις","ἄπρατα, πειρασεῖσθε τᾶς λιμῶ κακῶς.","Ἀλλ' ἀμφίθεσθε καὶ ταδὶ τὰ ῥυγχία,","κἤπειτεν εἰς τὸν σάκκον ὧδ' εἰσβαίνετε.","Ὅπως δὲ γρυλλιξεῖτε καὶ κοΐξετε","χἠσεῖτε φωνὰν χοιρίων μυστηρικῶν.","Ἐγὼν δὲ καρυξῶ Δικαιόπολιν ὅπα.","Δικαιόπολι, ἦ λῇς πρίασθαι χοιρία;"]},{"id":"ach-sp-0226","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί; Ἀνὴρ Μεγαρικός;"]},{"id":"ach-sp-0227","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ἀγορασοῦντες εἵκομες."]},{"id":"ach-sp-0228","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Πῶς ἔχετε;"]},{"id":"ach-sp-0229","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Διαπεινᾶμες ἀεὶ ποττὸ πῦρ."]},{"id":"ach-sp-0230","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' ἡδύ τοι νὴ τὸν Δί', ἢν αὐλὸς παρῇ.","Τί δ' ἄλλο πράττεθ' οἱ Μεγαρῆς νῦν;"]},{"id":"ach-sp-0231","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Οἷα δή.","Ὅκα μὲν ἐγὼν τηνῶθεν ἐμπορευόμαν,","τὤνδρες πρόβουλοι τοῦτ' ἔπρασσον τᾷ πόλι,","ὅπως τάχιστα καὶ κάκιστ' ἀπολοίμεθα."]},{"id":"ach-sp-0232","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Αὐτίκ' ἄρ' ἀπαλλάξεσθε πραγμάτων."]},{"id":"ach-sp-0233","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Σά μάν;"]},{"id":"ach-sp-0234","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί δ' ἄλλο Μεγαροῖ; Πῶς ὁ σῖτος ὤνιος;"]},{"id":"ach-sp-0235","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Πὰρ ἁμὲ πολυτίματος ᾇπερ τοὶ θεοί."]},{"id":"ach-sp-0236","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἅλας οὖν φέρεις;"]},{"id":"ach-sp-0237","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Οὐχ ὑμὲς αὐτῶν ἄρχετε;"]},{"id":"ach-sp-0238","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐδὲ σκόροδα;"]},{"id":"ach-sp-0239","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ποῖα σκόροδ'; Ὑμὲς τῶν ἀεί,","ὅκκ' εἰσβάλητε, τὼς ἀρωραῖοι μύες,","πάσσακι τὰς ἄγλιθας ἐξορύσσετε."]},{"id":"ach-sp-0240","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί δαὶ φέρεις;"]},{"id":"ach-sp-0241","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Χοίρως ἐγώνγα μυστικάς."]},{"id":"ach-sp-0242","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καλῶς λέγεις· ἐπίδειξον."]},{"id":"ach-sp-0243","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ἀλλὰ μὰν καλαί.","Ἄντεινον, αἰ λῇς· ὡς παχεῖα καὶ καλά."]},{"id":"ach-sp-0244","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τουτὶ τί ἦν τὸ πρᾶγμα;"]},{"id":"ach-sp-0245","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Χοῖρος ναὶ Δία."]},{"id":"ach-sp-0246","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί λέγεις σύ; ποδαπὴ χοῖρος ἥδε;"]},{"id":"ach-sp-0247","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Μεγαρικά.","Ἢ οὐ χοῖρός ἐσθ' ἅδ';"]},{"id":"ach-sp-0248","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐκ ἔμοιγε φαίνεται."]},{"id":"ach-sp-0249","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Οὐ δεινά; Θᾶσθε, τῶδε τᾶς ἀπιστίας·","οὔ φατι τάνδε χοῖρον εἶμεν. Ἀλλὰ μάν,","αἰ λῇς, περίδου μοι περὶ θυμιτιδᾶν ἁλῶν,","αἰ μή 'στιν οὗτος χοῖρος Ἑλλάνων νόμῳ."]},{"id":"ach-sp-0250","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' ἔστιν ἀνθρώπου γε."]},{"id":"ach-sp-0251","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ναὶ τὸν Διοκλέα,","ἐμά γα. Τὺ δέ νιν εἴμεναι τίνος δοκεῖς;","Ἦ λῇς ἀκοῦσαι φθεγγομένας;"]},{"id":"ach-sp-0252","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Νὴ τοὺς θεοὺς","ἔγωγε."]},{"id":"ach-sp-0253","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Φώνει δὴ ταχέως τι, χοιρίον.","Οὐ χρῆσθα; Σιγῇς, ὦ κάκιστ' ἀπολουμένα;","Πάλιν τυ ἀποισῶ ναὶ τὸν Ἑρμᾶν οἴκαδις."]},{"id":"ach-sp-0254","scene":"4","section_id":"ach-div-016","speaker":"Ragazza","speaker_ref":"#ragazza","lines":["Κοῒ κοΐ."]},{"id":"ach-sp-0255","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Αὕτα 'στὶ χοῖρος;"]},{"id":"ach-sp-0256","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Νῦν γε χοῖρος φαίνεται.","Ἀτὰρ ἐκτραφείς γε κύσθος ἔσται."]},{"id":"ach-sp-0257","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Πέντ' ἐτῶν,","σάφ' ἴσθι, ποττὰν ματέρ' εἰκασθήσεται."]},{"id":"ach-sp-0258","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' οὐχὶ θύσιμός ἐστιν αὑτηγί."]},{"id":"ach-sp-0259","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Σά μάν;","πᾶ δ' οὐκὶ θύσιμός ἐστι;"]},{"id":"ach-sp-0260","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κέρκον οὐκ ἔχει."]},{"id":"ach-sp-0261","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Νεαρὰ γάρ ἐστιν· ἀλλὰ δελφακουμένα","ἑξεῖ μεγάλαν τε καὶ παχεῖαν κἠρυθράν.","Ἀλλ' αἰ τράφειν λῇς, ἅδε τοι χοῖρος καλά."]},{"id":"ach-sp-0262","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὡς ξυγγενὴς ὁ κύσθος αὐτῆς θἀτέρᾳ."]},{"id":"ach-sp-0263","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ὁμοματρία γάρ ἐστι κἠκ τωὐτῶ πατρός.","Αἰ δ' ἀμπαχυνθῇ κἀναχνοιανθῇ τριχί,","κάλλιστος ἔσται χοῖρος Ἀφροδίτᾳ θύειν."]},{"id":"ach-sp-0264","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' οὐχὶ χοῖρος τἀφροδίτῃ θύεται,"]},{"id":"ach-sp-0265","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Οὐ χοῖρος Ἀφροδίτᾳ; Μόνᾳ γα δαιμόνων.","Καὶ γίνεταί γα τᾶνδε τᾶν χοίρων τὸ κρῆς","ἅδιστον ἂν τὸν ὀδελὸν ἀμπεπαρμένον."]},{"id":"ach-sp-0266","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἤδη δ' ἄνευ τῆς μητρὸς ἐσθίοιεν ἄν;"]},{"id":"ach-sp-0267","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ναὶ τὸν Ποτιδᾶ, καί κ' ἄνις γα τῶ πατρός."]},{"id":"ach-sp-0268","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί δ' ἐσθίει μάλιστα;"]},{"id":"ach-sp-0269","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Πάνθ' ἅ κα διδῷς.","Αὐτὸς δ' ἐρώτη."]},{"id":"ach-sp-0270","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Χύρρε χύρρε."]},{"id":"ach-sp-0271","scene":"4","section_id":"ach-div-016","speaker":"Ragazza","speaker_ref":"#ragazza","lines":["Κοῒ κοΐ."]},{"id":"ach-sp-0272","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τρώγοιτ' ἂν ἐρεβίνθους;"]},{"id":"ach-sp-0273","scene":"4","section_id":"ach-div-016","speaker":"Ragazza","speaker_ref":"#ragazza","lines":["Κοῒ Κοῒ κοΐ."]},{"id":"ach-sp-0274","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί δαί; Φιβάλεως ἰσχάδας;"]},{"id":"ach-sp-0275","scene":"4","section_id":"ach-div-016","speaker":"Ragazza","speaker_ref":"#ragazza","lines":["Κοῒ κοΐ."]},{"id":"ach-sp-0276","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["[Τί δαί; Σῦκα τρώγοις ἂν αὐτός;]"]},{"id":"ach-sp-0277","scene":"4","section_id":"ach-div-016","speaker":"Ragazza","speaker_ref":"#ragazza","lines":["[Κοῒ κοΐ.]"]},{"id":"ach-sp-0278","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὡς ὀξὺ πρὸς τὰς ἰσχάδας κεκράγατον.","Ἐνεγκάτω τις ἔνδοθεν τῶν ἰσχάδων","τοῖς χοιριδίοισιν. Ἆρα τρώξονται; Βαβαί,","οἷον ῥοθιάζουσ', ὦ πολυτίμηθ' Ἡράκλεις.","Ποδαπὰ τὰ χοιρί'; Ὡς Τραγασαῖα φαίνεται."]},{"id":"ach-sp-0279","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ἀλλ' οὐκὶ πάσας κατέτραγον τὰς ἰσχάδας.","Ἐγὼν γὰρ αὐτᾶν τάνδε μίαν ἀνειλόμαν."]},{"id":"ach-sp-0280","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Νὴ τὸν Δί', ἀστείω γε τὼ βοσκήματε.","Πόσου πρίωμαί σοι τὰ χοιρίδια; λέγε."]},{"id":"ach-sp-0281","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Τὸ μὲν ἅτερον τοῦτο σκορόδων τροπαλίδος,","τὸ δ' ἅτερον, αἰ λῇς, χοίνικος μόνας ἁλῶν."]},{"id":"ach-sp-0282","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὠνήσομαί σοι· περίμεν' αὐτοῦ."]},{"id":"ach-sp-0283","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ταῦτα δή.","Ἑρμᾶ 'μπολαῖε, τὰν γυναῖκα τὰν ἐμὰν","οὕτω μ' ἀποδόσθαι τάν τ' ἐμωυτῶ ματέρα."]},{"id":"ach-sp-0284","scene":"4","section_id":"ach-div-016","speaker":"Sicofante","speaker_ref":"#sicofante","lines":["Ὦνθρωπε, ποδαπός;"]},{"id":"ach-sp-0285","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Χοιροπώλας Μεγαρικός."]},{"id":"ach-sp-0286","scene":"4","section_id":"ach-div-016","speaker":"Sicofante","speaker_ref":"#sicofante","lines":["Τὰ χοιρίδια τοίνυν ἐγὼ φαίνω ταδὶ","πολέμια καὶ σέ."]},{"id":"ach-sp-0287","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Τοῦτ' ἐκεῖν'· εἵκει πάλιν","ὅθενπερ ἀρχὰ τῶν κακῶν ἁμὶν ἔφυ."]},{"id":"ach-sp-0288","scene":"4","section_id":"ach-div-016","speaker":"Sicofante","speaker_ref":"#sicofante","lines":["Κλάων μεγαριεῖς. Οὐκ ἀφήσεις τὸν σάκον;"]},{"id":"ach-sp-0289","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Δικαιόπολι Δικαιόπολι, φαντάδδομαι."]},{"id":"ach-sp-0290","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὑπὸ τοῦ; Τίς ὁ φαίνων σ' ἐστίν; Ἁγορανόμοι,","τοὺς συκοφάντας οὐ θύραζ' ἐξείρξετε;","Τί δαὶ μαθὼν φαίνεις ἄνευ θρυαλλίδος;"]},{"id":"ach-sp-0291","scene":"4","section_id":"ach-div-016","speaker":"Sicofante","speaker_ref":"#sicofante","lines":["Οὐ γὰρ φανῶ τοὺς πολεμίους;"]},{"id":"ach-sp-0292","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κλάων γε σύ,","εἰ μὴ 'τέρωσε συκοφαντήσεις τρέχων."]},{"id":"ach-sp-0293","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Οἷον τὸ κακὸν ἐν ταῖς Ἀθάναις τοῦτ' ἔνι."]},{"id":"ach-sp-0294","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Θάρρει, Μεγαρίκ'· ἀλλ' ἧς τὰ χοιρίδι' ἀπέδου","τιμῆς, λαβὲ ταυτὶ τὰ σκόροδα καὶ τοὺς ἅλας,","καὶ χαῖρε πόλλ'·"]},{"id":"ach-sp-0295","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ἀλλ' ἁμὶν οὐκ ἐπιχώριον."]},{"id":"ach-sp-0296","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Πολυπραγμοσύνη 'στιν· ἐς κεφαλὴν τράποιτ' ἐμοί."]},{"id":"ach-sp-0297","scene":"4","section_id":"ach-div-016","speaker":"Megarese","speaker_ref":"#megarese","lines":["Ὦ χοιρίδια, πειρῆσθε κἄνις τῶ πατρὸς","παίειν ἐφ' ἁλὶ τὰν μᾶδδαν, αἴ κά τις διδῷ."]},{"id":"ach-sp-0298","scene":"4","section_id":"ach-div-016","speaker":"Coro","speaker_ref":"#coro","lines":["Εὐδαιμονεῖ γ' ἅνθρωπος. Οὐκ","ἤκουσας οἷ προβαίνει","τὸ πρᾶγμα τοῦ βουλεύματος;","Καρπώσεται γὰρ ἁνὴρ","ἐν τἀγορᾷ καθήμενος·","κἂν εἰσίῃ τις Κτησίας","ἢ συκοφάντης ἄλλος, οἰ-","μώζων καθεδεῖται·","οὐδ' ἄλλος ἀνθρώπων ὑπο-","ψωνῶν σε πημανεῖ τι,","οὐδ' ἐξομόρξεται Πρέπις","τὴν εὐρυπρωκτίαν σοι,","οὐδ' ὠστιεῖ Κλεωνύμῳ·","χλαῖναν δ' ἔχων φανὴν δίει","κοὐ ξυντυχών σ' Ὑπέρβολος","δικῶν ἀναπλήσει·","οὐδ' ἐντυχὼν ἐν τἀγορᾷ","πρόσεισί σοι βαδίζων","Κρατῖνος ἀεὶ κεκαρμένος","μοιχὸν μιᾷ μαχαίρᾳ,","ὁ περιπόνηρος Ἀρτέμων,","ὁ ταχὺς ἄγαν τὴν μουσικήν,","ὄζων κακὸν τῶν μασχαλῶν","πατρὸς Τραγασαίου·","οὐδ' αὖθις αὖ σε σκώψεται","Παύσων ὁ παμπόνηρος","Λυσίστρατός τ' ἐν τἀγορᾷ,","Χολαργέων ὄνειδος,","ὁ περιαλουργὸς τοῖς κακοῖς,","ῥιγῶν τε καὶ πεινῶν ἀεὶ","πλεῖν ἢ τριάκονθ' ἡμέρας","τοῦ μηνὸς ἑκάστου."]},{"id":"ach-sp-0299","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Ἴττω Ἡρακλεῖς, ἔκαμόν γα τὰν τύλαν κακῶς.","Κατάθου τὺ τὰν γλάχων' ἀτρέμας, Ἰσμεινία·","ὑμὲς δ', ὅσοι Θείβαθεν αὐλειταὶ πάρα,","τοῖς ὀστίνοις φυσεῖτε τὸν πρωκτὸν κυνός."]},{"id":"ach-sp-0300","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Παῦ'· ἐς κόρακας. Οἱ σφῆκες, οὐκ ἀπὸ τῶν θυρῶν;","Πόθεν προσέπτονθ' οἱ κακῶς ἀπολούμενοι","ἐπὶ τὴν θύραν μοι Χαιριδῆς βομβαύλιοι;"]},{"id":"ach-sp-0301","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Νεὶ τὸν Ἰόλαν ἐπιχαρίτως ‹τύ› γ', ὦ ξένε·","Θείβαθε γὰρ φυσάντες ἐξόπισθέ μου","τἄνθια τᾶς γλάχωνος ἀπέκιξαν χαμαί.","Ἀλλ' εἴ τι βούλει, πρίασο τῶν ἐγὼ φέρω,","τῶν ὀρταλίχων ἢ τῶν τετραπτερυλλίδων."]},{"id":"ach-sp-0302","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ χαῖρε, κολλικοφάγε Βοιωτίδιον.","Τί φέρεις;"]},{"id":"ach-sp-0303","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Ὅσ' ἐστὶν ἀγαθὰ Βοιωτοῖς ἁπλῶς,","ὀρίγανον, γλαχώ, ψιάθως, θρυαλλίδας,","νάσσας, κολοιώς, ἀτταγᾶς, φαλαρίδας,","τροχίλως, κολύμβως."]},{"id":"ach-sp-0304","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὡσπερεὶ χειμὼν ἄρα","ὀρνιθίας εἰς τὴν ἀγορὰν ἐλήλυθας."]},{"id":"ach-sp-0305","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Καὶ μὰν φέρω χᾶνας, λαγώς, ἀλώπεκας,","σκάλοπας, ἐχίνως, αἰελώρως, πικτίδας,","ἰκτίδας, ἐνύδριας, ἐγχέλιας Κωπαΐδας."]},{"id":"ach-sp-0306","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ τερπνότατον σὺ τέμαχος ἀνθρώποις φέρων,","δός μοι προσειπεῖν, εἰ φέρεις, τὰς ἐγχέλεις."]},{"id":"ach-sp-0307","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Πρέσβειρα πεντήκοντα Κωπᾴδων κορᾶν,","ἔκβαθι τῶδε κἠπιχάριτται τῷ ξένῳ."]},{"id":"ach-sp-0308","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ φιλτάτη σὺ καὶ πάλαι ποθουμένη,","ἦλθες ποθεινὴ μὲν τρυγῳδικοῖς χοροῖς,","φίλη δὲ Μορύχῳ. Δμῶες, ἐξενέγκατε","τὴν ἐσχάραν μοι δεῦρο καὶ τὴν ῥιπίδα.","Σκέψασθε, παῖδες, τὴν ἀρίστην ἔγχελυν,","ἥκουσαν ἕκτῳ μόλις ἔτει ποθουμένην.","Προσείπατ' αὐτὴν, ὦ τέκν'· ἄνθρακας δ' ἐγὼ","ὑμῖν παρέξω τῆσδε τῆς ξένης χάριν.","Ἀλλ' εἴσφερ' αὐτήν· μηδὲ γὰρ θανών ποτε","σοῦ χωρὶς εἴην ἐντετευτλιωμένης."]},{"id":"ach-sp-0309","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Ἐμοὶ δὲ τιμὰ τᾶσδε πᾶ γενείσεται;"]},{"id":"ach-sp-0310","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀγορᾶς τέλος ταύτην γέ που δώσεις ἐμοί.","Ἀλλ' εἴ τι πωλεῖς τῶνδε τῶν ἄλλων, λέγε."]},{"id":"ach-sp-0311","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Ἰώγα ταῦτα πάντα."]},{"id":"ach-sp-0312","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Φέρε, πόσου λέγεις;","Ἢ φορτί' ἕτερ' ἐνθένδ' ἐκεῖσ' ἄξεις ἰών;"]},{"id":"ach-sp-0313","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Ὅ τι γ' ἔστ' Ἀθάνασ', ἐν Βοιωτοῖσιν δὲ μή."]},{"id":"ach-sp-0314","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀφύας ἄρ' ἄξεις πριάμενος Φαληρικὰς","ἢ κέραμον."]},{"id":"ach-sp-0315","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Ἀφύας εἲ κέραμον; Ἀλλ' ἔντ' ἐκεῖ·","ἀλλ' ὅ τι πὰρ ἁμὶν μεί 'στι, τᾶδε δ' αὖ πολύ."]},{"id":"ach-sp-0316","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐγᾦδα τοίνυν· συκοφάντην ἔξαγε,","ὥσπερ κέραμον ἐνδησάμενος."]},{"id":"ach-sp-0317","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Νεὶ τὼ σιώ,","λάβοιμι μέντἂν κέρδος ἀγαγὼν καὶ πολύ,","ἇπερ πίθακον ἀλιτρίας πολλᾶς πλέων."]},{"id":"ach-sp-0318","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καὶ μὴν ὁδὶ Νίκαρχος ἔρχεται φανῶν."]},{"id":"ach-sp-0319","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Μικκός γα μᾶκος οὗτος."]},{"id":"ach-sp-0320","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλὰ πᾶν κακόν."]},{"id":"ach-sp-0321","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Ταυτὶ τίνος τὰ φορτί' ἐστί;"]},{"id":"ach-sp-0322","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Τῶδ' ἐμὰ","Θείβαθεν, ἴττω Δεύς."]},{"id":"ach-sp-0323","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Ἐγὼ τοίνυν ὁδὶ","φαίνω πολέμια ταῦτα."]},{"id":"ach-sp-0324","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Τί δὲ κακὸν παθὼν","ὀρναπετίοισι πόλεμον ἤρα καὶ μάχαν;"]},{"id":"ach-sp-0325","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Καὶ σέ γε φανῶ πρὸς τοῖσδε."]},{"id":"ach-sp-0326","scene":"4","section_id":"ach-div-016","speaker":"Tebano","speaker_ref":"#tebano","lines":["Τί ἀδικείμενος;"]},{"id":"ach-sp-0327","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Ἐγὼ φράσω σοι τῶν περιεστώτων χάριν.","Ἐκ τῶν πολεμίων εἰσάγεις θρυαλλίδα."]},{"id":"ach-sp-0328","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἔπειτα φαίνεις δῆτα διὰ θρυαλλίδα;"]},{"id":"ach-sp-0329","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Αὕτη γὰρ ἐμπρήσειεν ἂν τὸ νεώριον."]},{"id":"ach-sp-0330","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Νεώριον θρυαλλίς;"]},{"id":"ach-sp-0331","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Οἶμαι."]},{"id":"ach-sp-0332","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τίνι τρόπῳ;"]},{"id":"ach-sp-0333","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Ἐνθεὶς ἂν εἰς τίφην ἀνὴρ Βοιώτιος","ἅψας ἂν εἰσπέμψειεν εἰς τὸ νεώριον","δι' ὑδρορρόας, βορέαν ἐπιτηρήσας μέγαν.","Κεἴπερ λάβοιτο τῶν νεῶν τὸ πῦρ ἅπαξ,","σελαγοῖντ' ἂν εὐθύς."]},{"id":"ach-sp-0334","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ κάκιστ' ἀπολούμενε,","σελαγοῖντ' ἂν ὑπὸ τίφης τε καὶ θρυαλλίδος;"]},{"id":"ach-sp-0335","scene":"4","section_id":"ach-div-016","speaker":"Nicarco","speaker_ref":"#nicarco","lines":["Μαρτύρομαι."]},{"id":"ach-sp-0336","scene":"4","section_id":"ach-div-016","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ξυλλάμβαν' αὐτοῦ τὸ στόμα·","δός μοι φορυτόν, ἵν' αὐτὸν ἐνδήσας φέρω","ὥσπερ κέραμον, ἵνα μὴ καταγῇ φερόμενος."]},{"id":"ach-sp-0337","scene":"Coro 3","section_id":"ach-div-017","speaker":"Coro","speaker_ref":"#coro","lines":["Ἔνδησον, ὦ βέλτιστε, τῷ","ξένῳ καλῶς τὴν ἐμπολὴν","οὕτως ὅπως","ἂν μὴ φέρων κατάξῃ"]},{"id":"ach-sp-0338","scene":"Coro 3","section_id":"ach-div-017","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐμοὶ μελήσει ταῦτ', ἐπεί","τοι καὶ ψοφεῖ λάλον τι καὶ","πυρορραγὲς","κἄλλως θεοῖσιν ἐχθρόν."]},{"id":"ach-sp-0339","scene":"Coro 3","section_id":"ach-div-017","speaker":"Coro","speaker_ref":"#coro","lines":["Τί χρήσεταί ποτ' αὐτῷ;"]},{"id":"ach-sp-0340","scene":"Coro 3","section_id":"ach-div-017","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Πάγχρηστον ἄγγος ἔσται,","κρατὴρ κακῶν, τριπτὴρ δικῶν,","φαίνειν ὑπευθύνους λυχνοῦ-","χος καὶ κύλιξ","τὰ πράγματ' ἐγκυκᾶσθαι."]},{"id":"ach-sp-0341","scene":"Coro 3","section_id":"ach-div-017","speaker":"Coro","speaker_ref":"#coro","lines":["Πῶς δ' ἂν πεποιθοίη τις ἀγ-","γείῳ τοιούτῳ χρώμενος","κατ' οἰκίαν","τοσόνδ' ἀεὶ ψοφοῦντι;"]},{"id":"ach-sp-0342","scene":"Coro 3","section_id":"ach-div-017","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["ἘἸσχυρόν ἐστιν, ὦγάθ', ὥστ'","οὐκ ἂν καταγείη ποτ', εἴ-","περ ἐκ ποδῶν","κατωκάρα κρέμαιτο."]},{"id":"ach-sp-0343","scene":"Coro 3","section_id":"ach-div-017","speaker":"Coro","speaker_ref":"#coro","lines":["Ἤδη καλῶς ἔχει σοι."]},{"id":"ach-sp-0344","scene":"Coro 3","section_id":"ach-div-017","speaker":"Tebano","speaker_ref":"#tebano","lines":["Μέλλω γά τοι θερίδδειν."]},{"id":"ach-sp-0345","scene":"Coro 3","section_id":"ach-div-017","speaker":"Coro","speaker_ref":"#coro","lines":["Ἀλλ', ὦ ξένων βέλτιστε, συν-","θέριζε καὶ[τοῦτον λαβὼν]πρόσβαλλ' ὅποι","βούλει φέρων","πρὸς πάντα συκοφάντην."]},{"id":"ach-sp-0346","scene":"5","section_id":"ach-div-020","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Μόλις γ' ἐνέδησα τὸν κακῶς ἀπολούμενον.","Αἴρου λαβὼν τὸν κέραμον, ὦ Βοιώτιε."]},{"id":"ach-sp-0347","scene":"5","section_id":"ach-div-020","speaker":"Tebano","speaker_ref":"#tebano","lines":["Ὑπόκυπτε τὰν τύλαν ἰών, Ἰσμείνιχε."]},{"id":"ach-sp-0348","scene":"5","section_id":"ach-div-020","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Χὤπως κατοίσεις αὐτὸν εὐλαβουμένως.","Πάντως μὲν οἴσεις οὐδὲν ὑγιές, ἀλλ' ὅμως·","κἂν τοῦτο κερδάνῃς ἄγων τὸ φορτίον,","εὐδαιμονήσεις συκοφαντῶν γ' οὕνεκα."]},{"id":"ach-sp-0349","scene":"5","section_id":"ach-div-020","speaker":"Messaggero di Lamaco","speaker_ref":"#messaggero-lamaco","lines":["Δικαιόπολι."]},{"id":"ach-sp-0350","scene":"5","section_id":"ach-div-020","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί ἐστι; Τί με βωστρεῖς;"]},{"id":"ach-sp-0351","scene":"5","section_id":"ach-div-020","speaker":"Messaggero di Lamaco","speaker_ref":"#messaggero-lamaco","lines":["Ὅ τι;","ἐκέλευε Λάμαχός σε ταυτησὶ δραχμῆς","εἰς τοὺς Χοᾶς αὑτῷ μεταδοῦναι τῶν κιχλῶν,","τριῶν δραχμῶν δ' ἐκέλευε Κωπᾷδ' ἔγχελυν."]},{"id":"ach-sp-0352","scene":"5","section_id":"ach-div-020","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὁ ποῖος οὗτος Λάμαχος τὴν ἔγχελυν;"]},{"id":"ach-sp-0353","scene":"5","section_id":"ach-div-020","speaker":"Messaggero di Lamaco","speaker_ref":"#messaggero-lamaco","lines":["Ὁ δεινός, ὁ ταλαύρινος, ὃς τὴν Γοργόνα","πάλλει κραδαίνων τρεῖς κατασκίους λόφους."]},{"id":"ach-sp-0354","scene":"5","section_id":"ach-div-020","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐκ ἂν μὰ Δί', εἰ δοίη γέ μοι τὴν ἀσπίδα","ἀλλ' ἐπὶ ταρίχει τοὺς λόφους κραδαινέτω","ἢν δ' ἀπολιγαίνῃ, τοὺς ἀγορανόμους καλῶ.","Ἐγὼ δ' ἐμαυτῷ τόδε λαβὼν τὸ φορτίον","εἴσειμ' ὑπαὶ πτερύγων κιχλᾶν καὶ κοψίχων."]},{"id":"ach-sp-0355","scene":"Coro 4","section_id":"ach-div-021","speaker":"Coro","speaker_ref":"#coro","lines":["Εἶδες, ὦ πᾶσα πόλι, τὸν φρόνιμον ἄνδρα, τὸν ὑπέρσοφον,","οἷ' ἔχει σπεισάμενος ἐμπορικὰ χρήματα διεμπολᾶν,","ὧν τὰ μὲν ἐν οἰκίᾳ χρήσιμα, τὰ δ' αὖ πρέπει χλιαρὰ κατεσθίειν.","Αὐτόματα πάντ' ἀγαθὰ τῷδέ γε πορίζεται.","Οὐδέποτ' ἐγὼ Πόλεμον οἴκαδ' ὑποδέξομαι,","οὐδὲ παρ' ἐμοί ποτε τὸν Ἁρμόδιον ᾄσεται","ξυγκατακλινείς, ὅτι πάροινος ἁνὴρ ἔφυ,","ὅστις ἐπὶ πάντ' ἀγάθ' ἔχοντας ἐπικωμάσας","ἠργάσατο πάντα κακά, κἀνέτρεπε κἀξέχει","κἀμάχετο καὶ προσέτι πολλὰ προκαλουμένου·","\"Πῖνε, κατάκεισο, λαβὲ τήνδε φιλοτησίαν,\"","τὰς χάρακας ἧπτε πολὺ μᾶλλον ἔτι τῷ πυρί,","ἐξέχει θ' ἡμῶν βίᾳ τὸν οἶνον ἐκ τῶν ἀμπέλων."]},{"id":"ach-sp-0356","scene":"Coro 4","section_id":"ach-div-021","speaker":"Coro","speaker_ref":"#coro","lines":["Ἐπτέρωταί τ' ἐπὶ τὸ δεῖπνον ἅμα καὶ μεγάλα δὴ φρονεῖ,","τοῦ βίου δ' ἐξέβαλε δεῖγμα ‹τάδε› τὰ πτερὰ πρὸ τῶν θυρῶν.","Ὦ Κύπριδι τῇ καλῇ καὶ Χάρισι ταῖς φίλαις ξύντροφε Διαλλαγή,","ὡς καλὸν ἔχουσα τὸ πρόσωπον ἄρ' ἐλάνθανες.","Πῶς ἂν ἐμὲ καὶ σέ τις Ἔρως ξυναγάγοι λαβών","ὥσπερ ὁ γεγραμμένος ἔχων στέφανον ἀνθέμων;","Ἢ πάνυ γερόντιον ἴσως νενόμικάς με σύ;","Ἀλλά σε λαβὼν τρία δοκῶ γ' ἂν ἔτι προσβαλεῖν·","πρῶτα μὲν ἂν ἀμπελίδος ὄρχον ἐλάσαι μακρόν,","εἶτα παρὰ τόνδε νέα μοσχίδια συκίδων,","καὶ τὸ τρίτον ἡμερίδος ὄσχον, ὁ γέρων ὁδί,","καὶ περὶ τὸ χωρίον ἐλᾷδας ἅπαν ἐν κύκλῳ,","ὥστ' ἀλείφεσθαι σ' ἀπ' αὐτῶν κἀμὲ ταῖς νουμηνίαις."]},{"id":"ach-sp-0357","scene":"Coro 4","section_id":"ach-div-021","speaker":"Araldo","speaker_ref":"#araldo","lines":["Ἀκούετε λεῴ· κατὰ τὰ πάτρια τοὺς Χοᾶς","πίνειν ὑπὸ τῆς σάλπιγγος· ὃς δ' ἂν ἐκπίῃ","πρώτιστος, ἀσκὸν Κτησιφῶντος λήψεται."]},{"id":"ach-sp-0358","scene":"Coro 4","section_id":"ach-div-021","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ παῖδες, ὦ γυναῖκες, οὐκ ἠκούσατε;","Τί δρᾶτε; Τοῦ κήρυκος οὐκ ἀκούετε;","Ἀναβράττετ', ἐξοπτᾶτε, τρέπετ', ἀφέλκετε","τὰ λαγῷα ταχέως, τοὺς στεφάνους ἀνείρετε.","Φέρε τοὺς ὀβελίσκους, ἵν' ἀναπείρω τὰς κίχλας."]},{"id":"ach-sp-0359","scene":"Coro 4","section_id":"ach-div-021","speaker":"Coro","speaker_ref":"#coro","lines":["Ζηλῶ σε τῆς εὐβουλίας,","μᾶλλον δὲ τῆς εὐωχίας,","ἄνθρωπε, τῆς παρούσης"]},{"id":"ach-sp-0360","scene":"Coro 4","section_id":"ach-div-021","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί δῆτ', ἐπειδὰν τὰς κίχλας","ὀπτωμένας ἴδητε;"]},{"id":"ach-sp-0361","scene":"Coro 4","section_id":"ach-div-021","speaker":"Coro","speaker_ref":"#coro","lines":["Οἶμαί σε καὶ τοῦτ' εὖ λέγειν."]},{"id":"ach-sp-0362","scene":"Coro 4","section_id":"ach-div-021","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τὸ πῦρ ὑποσκάλευε."]},{"id":"ach-sp-0363","scene":"Coro 4","section_id":"ach-div-021","speaker":"Coro","speaker_ref":"#coro","lines":["Ἤκουσας ὡς μαγειρικῶς","κομψῶς τε καὶ δειπνητικῶς","αὑτῷ διακονεῖται;"]},{"id":"ach-sp-0364","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Οἴμοι τάλας."]},{"id":"ach-sp-0365","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ Ἡράκλεις, τίς οὑτοσί;"]},{"id":"ach-sp-0366","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Ἀνὴρ κακοδαίμων."]},{"id":"ach-sp-0367","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κατὰ σεαυτόν νυν τρέπου."]},{"id":"ach-sp-0368","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Ὦ φίλτατε, σπονδαὶ γάρ εἰσι σοὶ μόνῳ,","μέτρησον εἰρήνης τί μοι, κἂν πέντ' ἔτη."]},{"id":"ach-sp-0369","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί δ' ἔπαθες;"]},{"id":"ach-sp-0370","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Ἐπετρίβην ἀπολέσας τὼ βόε."]},{"id":"ach-sp-0371","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Πόθεν;"]},{"id":"ach-sp-0372","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Ἀπὸ Φυλῆς ἔλαβον οἱ Βοιώτιοι."]},{"id":"ach-sp-0373","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦ τρισκακόδαιμον, εἶτα λευκὸν ἀμπέχει;"]},{"id":"ach-sp-0374","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Καὶ ταῦτα μέντοι νὴ Δί' ὥπερ μ' ἐτρεφέτην","ἐν πᾶσι βολίτοις."]},{"id":"ach-sp-0375","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Εἶτα νυνὶ τοῦ δέει;"]},{"id":"ach-sp-0376","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Ἀπόλωλα τὠφθαλμὼ δακρύων τὼ βόε.","Ἀλλ' εἴ τι κήδει Δερκέτου Φυλασίου,","ὑπάλειψον εἰρήνῃ με τὠφθαλμὼ ταχύ."]},{"id":"ach-sp-0377","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ', ὦ πόνηρ', οὐ δημοσιεύων τυγχάνω."]},{"id":"ach-sp-0378","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Ἴθ' ἀντιβολῶ σ', ἤν πως κομίσωμαι τὼ βόε."]},{"id":"ach-sp-0379","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐκ ἔστιν, ἀλλὰ κλᾶε πρὸς τοὺς Πιττάλου."]},{"id":"ach-sp-0380","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Σὺ δ' ἀλλά μοι σταλαγμὸν εἰρήνης ἕνα","εἰς τὸν καλαμίσκον ἐνστάλαξον τουτονί."]},{"id":"ach-sp-0381","scene":"6","section_id":"ach-div-025","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὐδ' ἂν στριβιλικίγξ· ἀλλ' ἀπιὼν οἴμωζέ ποι."]},{"id":"ach-sp-0382","scene":"6","section_id":"ach-div-025","speaker":"Contadino","speaker_ref":"#contadino","lines":["Οἴμοι κακοδαίμων τοῖν γεωργοῖν βοιδίοιν."]},{"id":"ach-sp-0383","scene":"Coro 5","section_id":"ach-div-026","speaker":"Coro","speaker_ref":"#coro","lines":["Ἁνὴρ ἀνηύρηκέν τι ταῖς","σπονδαῖσιν ἡδύ, κοὐκ ἔοι-","κεν οὐδενὶ μεταδώσειν."]},{"id":"ach-sp-0384","scene":"Coro 5","section_id":"ach-div-026","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κατάχει σὺ τῆς χορδῆς τὸ μέλι·","ὰς σηπίας στάθευε."]},{"id":"ach-sp-0385","scene":"Coro 5","section_id":"ach-div-026","speaker":"Coro","speaker_ref":"#coro","lines":["Ἤκουσας ὀρθιασμάτων;"]},{"id":"ach-sp-0386","scene":"Coro 5","section_id":"ach-div-026","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὀπτᾶτε τἀγχέλεια."]},{"id":"ach-sp-0387","scene":"Coro 5","section_id":"ach-div-026","speaker":"Coro","speaker_ref":"#coro","lines":["Ἀποκτενεῖς λιμῷ 'μὲ καὶ","τοὺς γείτονας κνίσῃ τε καὶ","φωνῇ τοιαῦτα λάσκων."]},{"id":"ach-sp-0388","scene":"Coro 5","section_id":"ach-div-026","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὀπτᾶτε ταυτὶ καὶ καλῶς ξανθίζετε."]},{"id":"ach-sp-0389","scene":"6","section_id":"ach-div-028","speaker":"Damigella","speaker_ref":"#damigella","lines":["Δικαιόπολι,‹Δικαιόπολι.›"]},{"id":"ach-sp-0390","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τίς οὑτοσί;"]},{"id":"ach-sp-0391","scene":"6","section_id":"ach-div-028","speaker":"Damigella","speaker_ref":"#damigella","lines":["Ἔπεμψέ τίς σοι νυμφίος ταυτὶ κρέα","ἐκ τῶν γάμων."]},{"id":"ach-sp-0392","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καλῶς γε ποιῶν ὅστις ἦν."]},{"id":"ach-sp-0393","scene":"6","section_id":"ach-div-028","speaker":"Damigella","speaker_ref":"#damigella","lines":["Ἐκέλευε δ' ἐγχέαι σε τῶν κρεῶν χάριν,","ἵνα μὴ στρατεύοιτ', ἀλλὰ κινοίη μένων,","εἰς τὸν ἀλάβαστον κύαθον εἰρήνης ἕνα."]},{"id":"ach-sp-0394","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀπόφερ', ἀπόφερε τὰ κρέα καὶ μή μοι δίδου,","ὡς οὐκ ἂν ἐγχέαιμι χιλιῶν δραχμῶν.","Ἀλλ' αὑτηὶ τίς ἐστιν;"]},{"id":"ach-sp-0395","scene":"6","section_id":"ach-div-028","speaker":"Damigella","speaker_ref":"#damigella","lines":["Ἡ νυμφεύτρια","δεῖται παρὰ τῆς νύμφης τι σοὶ λέξαι μόνῳ."]},{"id":"ach-sp-0396","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Φέρε δή, τί σὺ λέγεις; Ὡς γέλοιον, ὦ θεοί,","τὸ δέημα τῆς νύμφης, ὃ δεῖταί μου σφόδρα,","ὅπως ἂν οἰκουρῇ τὸ πέος τοῦ νυμφίου.","Φέρε δεῦρο τὰς σπονδάς, ἵν' αὐτῇ δῶ μόνῃ,","ὁτιὴ γυνή 'στι τοῦ πολέμου τ' οὐκ αἰτία.","Ὕπεχ' ὧδε δεῦρο τοὐξάλειπτρον, ὦ γύναι.","Οἶσθ' ὡς ποείτω; τοῦτο τῇ νύμφῃ φράσον·","Ὅταν στρατιώτας καταλέγωσι, τουτῳὶ","νύκτωρ ἀλειφέτω τὸ πέος τοῦ νυμφίου.","Ἀπόφερε τὰς σπονδάς. Φέρε τὴν οἰνήρυσιν,","ἵν' οἶνον ἐγχέω λαβὼν εἰς τοὺς Χοᾶς."]},{"id":"ach-sp-0397","scene":"6","section_id":"ach-div-028","speaker":"Coro","speaker_ref":"#coro","lines":["Καὶ μὴν ὁδί τις τὰς ὀφρῦς ἀνεσπακὼς","ὥσπερ τι δεινὸν ἀγγελῶν ἐπείγεται."]},{"id":"ach-sp-0398","scene":"6","section_id":"ach-div-028","speaker":"Araldo","speaker_ref":"#araldo","lines":["Ἰὼ πόνοι τε καὶ μάχαι καὶ Λάμαχοι."]},{"id":"ach-sp-0399","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τίς ἀμφὶ χαλκοφάλαρα δώματα κτυπεῖ;"]},{"id":"ach-sp-0400","scene":"6","section_id":"ach-div-028","speaker":"Araldo","speaker_ref":"#araldo","lines":["Ἰέναι σ' ἐκέλευον οἱ στρατηγοὶ τήμερον","ταχέως λαβόντα τοὺς λόχους καὶ τοὺς λόφους·","κἄπειτα τηρεῖν νειφόμενον τὰς εἰσβολάς.","Ὑπὸ τοὺς Χοᾶς γὰρ καὶ Χύτρους αὐτοῖσί τις","ἤγγειλε λῃστὰς ἐμβαλεῖν Βοιωτίους."]},{"id":"ach-sp-0401","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἰὼ στρατηγοὶ πλείονες ἢ βελτίονες."]},{"id":"ach-sp-0402","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Οὐ δεινὰ μὴ 'ξεῖναί με μηδ' ἑορτάσαι;"]},{"id":"ach-sp-0403","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἰὼ στράτευμα πολεμολαμαχαϊκόν."]},{"id":"ach-sp-0404","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Οἴμοι κακοδαίμων, καταγελᾷς ἤδη σύ μου."]},{"id":"ach-sp-0405","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Βούλει μάχεσθαι Γηρυόνῃ τετραπτίλῳ;"]},{"id":"ach-sp-0406","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Αἰαῖ,","οἵαν ὁ κῆρυξ ἀγγελίαν ἤγγειλέ μοι."]},{"id":"ach-sp-0407","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Αἰαῖ, τίνα δ' αὖ 'μοὶ προστρέχει τις ἀγγελῶν;"]},{"id":"ach-sp-0408","scene":"6","section_id":"ach-div-028","speaker":"Messaggero","speaker_ref":"#messaggero-dioniso","lines":["Δικαιόπολι."]},{"id":"ach-sp-0409","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί ἐστιν;"]},{"id":"ach-sp-0410","scene":"6","section_id":"ach-div-028","speaker":"Messaggero","speaker_ref":"#messaggero-dioniso","lines":["Ἐπὶ δεῖπνον ταχὺ","βάδιζε τὴν κίστην λαβὼν καὶ τὸν χοᾶ.","Ὁ τοῦ Διονύσου γάρ σ' ἱερεὺς μεταπέμπεται.","Ἀλλ' ἐγκόνει· δειπνεῖν κατακωλύεις πάλαι.","Τὰ δ' ἄλλα πάντ' ἐστὶν παρεσκευασμένα,","κλῖναι, τράπεζαι, προσκεφάλαια, στρώματα,","στέφανοι, μύρον, τραγήμαθ', ‑ αἱ πόρναι πάρα, ‑","ἄμυλοι, πλακοῦντες, σησαμοῦντες, ἴτρια,","ὀρχηστρίδες, τὸ Φίλταθ' Ἁρμόδι' οὐ, πάλαι.","Ἀλλ' ὡς τάχιστα σπεῦδε."]},{"id":"ach-sp-0411","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Κακοδαίμων ἐγώ."]},{"id":"ach-sp-0412","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καὶ γὰρ σὺ μεγάλην ἐπεγράφου τὴν Γοργόνα.","Σύγκλειε, καὶ δεῖπνόν τις ἐνσκευαζέτω."]},{"id":"ach-sp-0413","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Παῖ παῖ, φέρ' ἔξω δεῦρο τὸν γυλιὸν ἐμοί."]},{"id":"ach-sp-0414","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Παῖ παῖ, φέρ' ἔξω δεῦρο τὴν κίστην ἐμοί."]},{"id":"ach-sp-0415","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἅλας θυμίτας οἶσε, παῖ, καὶ κρόμμυα."]},{"id":"ach-sp-0416","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐμοὶ δὲ τεμάχη· κρομμύοις γὰρ ἄχθομαι."]},{"id":"ach-sp-0417","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Θρῖον ταρίχους οἶσε δεῦρο, παῖ, σαπροῦ."]},{"id":"ach-sp-0418","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κἀμοὶ σὺ δή, παῖ, θρῖον· ὀπτήσω δ' ἐκεῖ."]},{"id":"ach-sp-0419","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἔνεγκε δεῦρο τὼ πτερὼ τὠκ τοῦ κράνους."]},{"id":"ach-sp-0420","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐμοὶ δὲ τὰς φάττας γε φέρε καὶ τὰς κίχλας."]},{"id":"ach-sp-0421","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Καλόν γε καὶ λευκὸν τὸ τῆς στρούθου πτερόν."]},{"id":"ach-sp-0422","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καλόν γε καὶ ξανθὸν τὸ τῆς φάττης κρέας."]},{"id":"ach-sp-0423","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ὦνθρωπε, παῦσαι καταγελῶν μου τῶν ὅπλων."]},{"id":"ach-sp-0424","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὦνθρωπε, βούλει μὴ βλέπειν εἰς τὰς κίχλας;"]},{"id":"ach-sp-0425","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τὸ λοφεῖον ἐξένεγκε τῶν τριῶν λόφων."]},{"id":"ach-sp-0426","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κἀμοὶ λεκάνιον τῶν λαγῴων δὸς κρεῶν."]},{"id":"ach-sp-0427","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἀλλ' ἦ τριχόβρωτες τοὺς λόφους μου κατέφαγον;"]},{"id":"ach-sp-0428","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' ἦ πρὸ δείπνου τὴν μίμαρκυν κατέδομαι;"]},{"id":"ach-sp-0429","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ὦνθρωπε, βούλει μὴ προσαγορεύειν ἐμέ;"]},{"id":"ach-sp-0430","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Οὔκ, ἀλλ' ἐγὼ χὠ παῖς ἐρίζομεν πάλαι.","Βούλει περιδόσθαι κἀπιτρέψαι Λαμάχῳ,","πότερον ἀκρίδες ἥδιόν ἐστιν ἢ κίχλαι;"]},{"id":"ach-sp-0431","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Οἴμ' ὡς ὑβρίζεις."]},{"id":"ach-sp-0432","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τὰς ἀκρίδας κρίνει πολύ."]},{"id":"ach-sp-0433","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Παῖ παῖ, καθελών μοι τὸ δόρυ δεῦρ' ἔξω φέρε."]},{"id":"ach-sp-0434","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Παῖ παῖ, σὺ δ' ἀφελὼν δεῦρο τὴν χορδὴν φέρε."]},{"id":"ach-sp-0435","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Φέρε, τοῦ δόρατος ἀφελκύσωμαι τοὔλυτρον.","Ἔχ', ἀντέχου, παῖ."]},{"id":"ach-sp-0436","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καὶ σύ, παῖ, τοῦδ' ἀντέχου."]},{"id":"ach-sp-0437","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τοὺς κιλλίβαντας οἶσε, παῖ, τῆς ἀσπίδος."]},{"id":"ach-sp-0438","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καὶ τῆς ἐμῆς τοὺς κριβανίτας ἔκφερε."]},{"id":"ach-sp-0439","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Φέρε δεῦρο γοργόνωτον ἀσπίδος κύκλον."]},{"id":"ach-sp-0440","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κἀμοὶ πλακοῦντος τυρόνωτον δὸς κύκλον."]},{"id":"ach-sp-0441","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ταῦτ' οὐ κατάγελώς ἐστιν ἀνθρώποις πλατύς;"]},{"id":"ach-sp-0442","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ταῦτ' οὐ πλακοῦς δῆτ' ἐστὶν ἀνθρώποις γλυκύς;"]},{"id":"ach-sp-0443","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Κατάχει σύ, παῖ, τοὔλαιον. Ἐν τῷ χαλκίῳ","ἐνορῶ γέροντα δειλίας φευξούμενον."]},{"id":"ach-sp-0444","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κατάχει σὺ τὸ μέλι. Κἀνθάδ' εὔδηλος γέρων","κλάειν κελεύων Λάμαχον τὸν Γοργάσου."]},{"id":"ach-sp-0445","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Φέρε δεῦρο, παῖ, θώρακα πολεμιστήριον."]},{"id":"ach-sp-0446","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἔξαιρε, παῖ, θώρακα κἀμοὶ τὸν χοᾶ."]},{"id":"ach-sp-0447","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἐν τῷδε πρὸς τοὺς πολεμίους θωρήξομαι."]},{"id":"ach-sp-0448","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐν τῷδε πρὸς τοὺς συμπότας θωρήξομαι."]},{"id":"ach-sp-0449","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τὰ στρώματ', ὦ παῖ, δῆσον ἐκ τῆς ἀσπίδος."]},{"id":"ach-sp-0450","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τὸ δεῖπνον, ὦ παῖ, δῆσον ἐκ τῆς κιστίδος."]},{"id":"ach-sp-0451","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἐγὼ δ' ἐμαυτῷ τὸν γυλιὸν οἴσω λαβών."]},{"id":"ach-sp-0452","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐγὼ δὲ θοἰμάτιον λαβὼν ἐξέρχομαι."]},{"id":"ach-sp-0453","scene":"6","section_id":"ach-div-028","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τὴν ἀσπίδ' αἴρου καὶ βάδιζ', ὦ παῖ, λαβών.","Νείφει. Βαβαιάξ· χειμέρια τὰ πράγματα."]},{"id":"ach-sp-0454","scene":"6","section_id":"ach-div-028","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Αἴρου τὸ δεῖπνον· συμποτικὰ τὰ πράγματα."]},{"id":"ach-sp-0455","scene":"Coro 6","section_id":"ach-div-029","speaker":"Coro","speaker_ref":"#coro","lines":["Ἴτε δὴ χαίροντες ἐπὶ στρατιάν.","Ὡς ἀνομοίαν ἔρχεσθον ὁδόν·","τῷ μὲν πίνειν στεφανωσαμένῳ,","σοὶ δὲ ῥιγῶν καὶ προφυλάττειν,","τῷ δὲ καθεύδειν","μετὰ παιδίσκης ὡραιοτάτης,","ἀνατριβομένῳ γε τὸ δεῖνα."]},{"id":"ach-sp-0456","scene":"Coro 6","section_id":"ach-div-029","speaker":"Coro","speaker_ref":"#coro","lines":["Ἀντίμαχον τὸν Ψακάδος, τὸν ξυγγραφῆ, τὸν μελέων ποητήν,","ὡς μὲν ἁπλῷ λόγῳ κακῶς ἐξολέσειεν ὁ Ζεύς·","ὅς γ' ἐμὲ τὸν τλήμονα Λήναια χορηγῶν ἀπέλυσ' ἄδειπνον.","Ὃν ἔτ' ἐπίδοιμι τευθίδος","δεόμενον, ἡ δ' ὠπτημένη","σίζουσα πάραλος ἐπὶ τραπέζῃ κειμένη","ὀκέλλοι· κᾆτα μέλλοντος λαβεῖν","αὐτοῦ κύων ἁρπάσασα φεύγοι."]},{"id":"ach-sp-0457","scene":"Coro 6","section_id":"ach-div-029","speaker":"Coro","speaker_ref":"#coro","lines":["Τοῦτο μὲν αὐτῷ κακὸν ἕν, κᾆθ' ἕτερον νυκτερινὸν γένοιτο.","Ἠπιαλῶν γὰρ οἴκαδ' ἐξ ἱππασίας βαδίζων,","εἶτα πατάξειέ τις αὐτοῦ μεθύων τὴν κεφαλὴν Ὀρέστης","μαινόμενος· ὁ δὲ λίθον λαβεῖν","βουλόμενος ἐν σκότῳ λάβοι","τῇ χειρὶ πέλεθον ἀρτίως κεχεσμένον·","ἐπᾴξειεν δ' ἔχων τὸν μάρμαρον,","κἄπειθ' ἁμαρτὼν βάλοι Κρατῖνον."]},{"id":"ach-sp-0458","scene":"7","section_id":"ach-div-032","speaker":"Messaggero","speaker_ref":"#messaggero-finale","lines":["Ὦ δμῶες οἳ κατ' οἶκόν ἐστε Λαμάχου,","ὕδωρ, ὕδωρ ἐν χυτριδίῳ θερμαίνετε·","ὀθόνια, κηρωτὴν παρασκευάζετε,","ἔρι' οἰσυπηρά, λαμπάδιον περὶ τὸ σφυρόν.","Ἁνὴρ τέτρωται χάρακι διαπηδῶν τάφρον,","καὶ τὸ σφυρὸν παλίνορρον ἐξεκόκκισεν,","καὶ τῆς κεφαλῆς κατέαγε περὶ λίθῳ πεσών,","καὶ Γοργόν' ἐξήγειρεν ἐκ τῆς ἀσπίδος·","πτίλον δὲ τὸ μέγα κομπολακύθου κλάσας","πρὸς ταῖς πέτραισι δεινὸν ἐξηύδα μέλος·","\"Ὦ κλεινὸν ὄμμα νῦν πανύστατόν σ' ἰδὼν","λείπω φάος τόδ'. Οὐκέτ' ‹οὐδέν› εἰμ' ἐγώ.\"","Τοσαῦτα λέξας εἰς ὑδρορρόαν πεσὼν","ἀνίσταταί τε καὶ ξυναντᾷ δραπέτας","λῃστὰς ἐλαύνων καὶ κατασπέρχων δορί.","Ὁδὶ δὲ καὐτός. Ἀλλ' ἄνοιγε τὴν θύραν."]},{"id":"ach-sp-0459","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἀτταταῖ ἀτταταῖ,","στυγερὰ τάδε γε κρυερὰ πάθεα· τάλας ἐγώ.","Διόλλυμαι δορὸς ὑπὸ πολεμίου τυπείς.","Ἐκεῖνο δ' αἰακτὸν [οἰμωκτὸν] ἂν γένοιτό μοι,","Δικαιόπολις εἴ μ' ἴδοι τετρωμένον","κᾆτ' ἐγχάνοι ταῖς ἐμαῖς τύχαισιν."]},{"id":"ach-sp-0460","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀτταταῖ ἀτταταῖ,","τῶν τιτθίων, ὡς σκληρὰ καὶ κυδώνια.","Φιλήσατόν με μαλθακῶς, ὦ χρυσίω,","τὸ περιπεταστὸν κἀπιμανδαλωτόν.","Τὸν γὰρ χοᾶ πρῶτος ἐκπέπωκα."]},{"id":"ach-sp-0461","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ὦ συμφορὰ τάλαινα τῶν ἐμῶν κακῶν.","Ἰὼ ἰὼ τραυμάτων ἐπωδύνων."]},{"id":"ach-sp-0462","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἰὴ ἰή, χαῖρε, Λαμαχίππιον."]},{"id":"ach-sp-0463","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Στυγερὸς ἐγώ."]},{"id":"ach-sp-0464","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί με σὺ κυνεῖς;"]},{"id":"ach-sp-0465","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Μογερὸς ἐγώ."]},{"id":"ach-sp-0466","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τί με σὺ δάκνεις;"]},{"id":"ach-sp-0467","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Τάλας ἐγὼ [τῆς ἐν μάχῃ]ξυμβολῆς βαρείας."]},{"id":"ach-sp-0468","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Τοῖς Χουσὶ γάρ τις ξυμβολὰς ἐπράττετο;"]},{"id":"ach-sp-0469","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Ἰὼ ‹ἰώ,› Παιὰν Παιάν."]},{"id":"ach-sp-0470","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἀλλ' οὐχὶ νυνὶ τήμερον Παιώνια."]},{"id":"ach-sp-0471","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Λάβεσθέ μου, λάβεσθε τοῦ σκέλους· παπαῖ,","προσλάβεσθ', ὦ φίλοι."]},{"id":"ach-sp-0472","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἐμοῦ δέ γε σφὼ τοῦ πέους ἄμφω μέσου","προσλάβεσθ', ὦ φίλαι."]},{"id":"ach-sp-0473","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Εἰλιγγιῶ κάρα λίθῳ πεπληγμένος","καὶ σκοτοδινιῶ."]},{"id":"ach-sp-0474","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Κἀγὼ καθεύδειν βούλομαι καὶ στύομαι","καὶ σκοτοβινιῶ."]},{"id":"ach-sp-0475","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Θύραζέ μ' ἐξενέγκατ' εἰς τοῦ Πιττάλου","παιωνίαισι χερσίν."]},{"id":"ach-sp-0476","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὡς τοὺς κριτάς με φέρετε. Ποῦ 'στιν ὁ βασιλεύς;","Ἀπόδοτέ μοι τὸν ἀσκόν."]},{"id":"ach-sp-0477","scene":"7","section_id":"ach-div-032","speaker":"Lamaco","speaker_ref":"#lamaco","lines":["Λόγχη τις ἐμπέπηγέ μοι δι' ὀστέων ὀδυρτά."]},{"id":"ach-sp-0478","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ὁρᾶτε τουτονὶ κενόν. Τήνελλα καλλίνικος."]},{"id":"ach-sp-0479","scene":"7","section_id":"ach-div-032","speaker":"Coro","speaker_ref":"#coro","lines":["Τήνελλα δῆτ', εἴπερ καλεῖς γ', ὦ πρέσβυ, καλλίνικος."]},{"id":"ach-sp-0480","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Καὶ πρός γ' ἄκρατον ἐγχέας ἄμυστιν ἐξέλαψα."]},{"id":"ach-sp-0481","scene":"7","section_id":"ach-div-032","speaker":"Coro","speaker_ref":"#coro","lines":["Τήνελλά νυν, ὦ γεννάδα· χώρει λαβὼν τὸν ἀσκόν."]},{"id":"ach-sp-0482","scene":"7","section_id":"ach-div-032","speaker":"Diceopoli","speaker_ref":"#diceopoli","lines":["Ἕπεσθέ νυν ᾄδοντες· Ὦ τήνελλα καλλίνικος."]},{"id":"ach-sp-0483","scene":"7","section_id":"ach-div-032","speaker":"Coro","speaker_ref":"#coro","lines":["Ἀλλ' ἑψόμεσθα σὴν χάριν","τήνελλα καλλίνικον ᾄ-","δοντες σὲ καὶ τὸν ἀσκόν."]}]}};
